// ─── Bithumb MCP Error Hierarchy ───────────────────────────────────

export type ErrorType =
  | "ConfigError"
  | "AuthenticationError"
  | "RateLimitError"
  | "ValidationError"
  | "BithumbApiError"
  | "NetworkError"
  | "InternalError";

export interface ToolErrorPayload {
  error: true;
  type: ErrorType;
  code?: string;
  message: string;
  suggestion?: string;
  endpoint?: string;
  timestamp: string;
}

export class BithumbMcpError extends Error {
  public readonly type: ErrorType;
  public readonly code?: string;
  public readonly suggestion?: string;
  public readonly endpoint?: string;

  constructor(
    type: ErrorType,
    message: string,
    options?: {
      code?: string;
      suggestion?: string;
      endpoint?: string;
      cause?: unknown;
    },
  ) {
    super(message, options?.cause ? { cause: options.cause } : undefined);
    this.name = type;
    this.type = type;
    this.code = options?.code;
    this.suggestion = options?.suggestion;
    this.endpoint = options?.endpoint;
  }
}

export class ConfigError extends BithumbMcpError {
  constructor(message: string, suggestion?: string) {
    super("ConfigError", message, { suggestion });
  }
}

export class ValidationError extends BithumbMcpError {
  constructor(message: string, suggestion?: string) {
    super("ValidationError", message, { suggestion });
  }
}

export class RateLimitError extends BithumbMcpError {
  constructor(message: string, suggestion?: string, endpoint?: string) {
    super("RateLimitError", message, { suggestion, endpoint });
  }
}

export class AuthenticationError extends BithumbMcpError {
  constructor(message: string, suggestion?: string, endpoint?: string) {
    super("AuthenticationError", message, { suggestion, endpoint });
  }
}

export class BithumbApiError extends BithumbMcpError {
  constructor(
    message: string,
    options?: { code?: string; endpoint?: string; cause?: unknown },
  ) {
    super("BithumbApiError", message, options);
  }
}

export class NetworkError extends BithumbMcpError {
  constructor(message: string, endpoint?: string, cause?: unknown) {
    super("NetworkError", message, {
      endpoint,
      cause,
      suggestion: "Check network connectivity and try again.",
    });
  }
}

export class InternalError extends BithumbMcpError {
  constructor(message: string, cause?: unknown) {
    super("InternalError", message, { cause });
  }
}

// ─── Error → MCP payload ───────────────────────────────────────────

export function toToolErrorPayload(error: unknown): ToolErrorPayload {
  if (error instanceof BithumbMcpError) {
    return {
      error: true,
      type: error.type,
      code: error.code,
      message: error.message,
      suggestion: error.suggestion,
      endpoint: error.endpoint,
      timestamp: new Date().toISOString(),
    };
  }

  const message =
    error instanceof Error ? error.message : "An unexpected error occurred.";
  return {
    error: true,
    type: "InternalError",
    message,
    timestamp: new Date().toISOString(),
  };
}
