// ─── Withdraw Tools (Private) ─────────────────────────────────────

import type { ToolSpec } from "./types.js";
import {
  asRecord,
  compactObject,
  normalizeResponse,
  readNumber,
  readString,
  readStringArray,
  requireString,
} from "./helpers.js";
import { orderRateLimit, privateRateLimit } from "./common.js";
import { ValidationError } from "../utils/errors.js";

export function registerWithdrawTools(): ToolSpec[] {
  return [
    // ── 9. withdraw_get_chance ───────────────────────────────────────
    {
      name: "withdraw_get_chance",
      module: "withdraw",
      description:
        "출금 가능 정보를 조회합니다. Get withdrawal chance info (available balance, fees, limits). " +
        "Always call this before withdraw_coin to confirm supported net_type values, withdrawal fee, minimum amount, and daily limits. " +
        "For multi-network coins (USDT, USDC, XRP, etc.), this is the only way to discover valid net_type values — never guess.",
      isWrite: false,
      inputSchema: {
        type: "object",
        properties: {
          currency: {
            type: "string",
            description: "Currency symbol, e.g. BTC",
          },
          net_type: {
            type: "string",
            description: "Withdrawal network, e.g. BTC, DASH",
          },
        },
        required: ["currency", "net_type"],
      },
      handler: async (rawArgs, context) => {
        const args = asRecord(rawArgs);
        const response = await context.client.privateGet(
          "/v1/withdraws/chance",
          {
            currency: requireString(args, "currency"),
            net_type: requireString(args, "net_type"),
          },
          privateRateLimit("withdraw_get_chance"),
        );
        return normalizeResponse(response);
      },
    },

    // ── 10. withdraw_get ─────────────────────────────────────────────
    {
      name: "withdraw_get",
      module: "withdraw",
      description:
        "식별자(txid 또는 withdrawal_id) 1개로 특정 출금 1건을 조회합니다. 단건 조회의 canonical 도구. " +
        "Single withdrawal by one identifier. " +
        "Use when: you have one txid or withdrawal_id. " +
        "Do NOT use: to search history or filter by state — use withdraw_get_list instead. " +
        "식별자 폴백(중요): 입·출금은 txid를 1차 식별자로 쓴다. 맨 숫자 ID는 txid인지 withdrawal_id인지 값만으로 구분되지 않으므로(KRW는 둘 다 숫자), txid로 먼저 조회 → withdraw_not_found면 같은 값을 withdrawal_id로 재시도한 뒤에 '없음'으로 단정하라. A bare numeric ID is ambiguous (txid and withdrawal_id can both be numeric, esp. KRW) — query txid first; on withdraw_not_found, retry the same value as withdrawal_id before concluding 'not found'. " +
        'Example call: {"currency":"BTC","txid":"2025-07-31 15:12:24.407715"}. For a bare numeric ID, try {"currency":"KRW","txid":"55955615"} first; on withdraw_not_found, retry {"currency":"KRW","withdrawal_id":"43007582"}.',
      isWrite: false,
      inputSchema: {
        type: "object",
        properties: {
          currency: {
            type: "string",
            description: "Currency symbol, e.g. BTC",
          },
          withdrawal_id: {
            type: "string",
            description: "Withdrawal unique ID",
          },
          txid: {
            type: "string",
            description: "Withdrawal transaction ID",
          },
        },
        required: ["currency"],
      },
      handler: async (rawArgs, context) => {
        const args = asRecord(rawArgs);
        // Exposed param is `withdrawal_id`, but the Bithumb GET /v1/withdraw
        // endpoint expects it in the `uuid` field (legacy naming — the "uuid"
        // is actually the withdrawal_id, matching the cancel endpoint's name).
        const response = await context.client.privateGet(
          "/v1/withdraw",
          compactObject({
            currency: requireString(args, "currency"),
            uuid: readString(args, "withdrawal_id"),
            txid: readString(args, "txid"),
          }),
          privateRateLimit("withdraw_get"),
        );
        return normalizeResponse(response);
      },
    },

    // ── 11. withdraw_get_list ────────────────────────────────────────
    {
      name: "withdraw_get_list",
      module: "withdraw",
      description:
        "여러 출금을 검색하거나 상태로 거른 리스트를 조회합니다. 식별자가 1개뿐이면 withdraw_get(단건)을 쓰세요. " +
        "List of coin withdrawals (table-rendered; same fields as withdraw_get). " +
        "Use when: 'recent withdrawals' / filter by state / search across multiple txids. " +
        "Do NOT use: when you have a single txid or withdrawal_id — use withdraw_get instead. " +
        "식별자 폴백(리스트 검색 시): 입·출금은 txid를 1차 식별자로 쓴다. ID가 txid인지 uuid(withdrawal_ids)인지 불명확하면 txids로 먼저 조회 → 빈 배열이면 같은 값을 withdrawal_ids로 재시도(또는 사용자 질문)한 뒤에 '없음'으로 단정하라. If a txids search returns an empty array, the value may be a withdrawal_id — retry the same values via withdrawal_ids (or ask the user) before concluding 'not found'. " +
        "⚠️ 공백·쉼표 포함 txid 제약: 빗썸 목록 엔드포인트의 txids 필터는 값에 공백이나 쉼표가 있으면(올바로 percent-encode해도) 매칭하지 못한다(서버 제약). 그런 txid(예: 'EVENT_COUPON:4,649', '2025-08-04 20:33:13.452665')는 txids로 조회하지 말고 withdraw_get 단건(txid)으로 조회하라. A txid containing a space or comma cannot be matched by the list txids filter (server-side limitation, even when correctly encoded) — use the single-record withdraw_get with `txid` instead. " +
        'Example call (txid lookup): {"currency":"TRX","txids":["17d829e8..."]}',
      isWrite: false,
      inputSchema: {
        type: "object",
        properties: {
          currency: {
            type: "string",
            description: "Currency symbol, e.g. BTC",
          },
          state: {
            type: "string",
            enum: ["PROCESSING", "DONE", "CANCELLED"],
            description: "Withdrawal state filter",
          },
          withdrawal_ids: {
            type: "array",
            items: { type: "string" },
            description:
              "Filter by withdrawal IDs (uuids). Fallback identifier: if a txids lookup returned an empty array for a bare numeric ID, retry that value here (KRW uuids and txids are both numeric, so the value is ambiguous).",
          },
          txids: {
            type: "array",
            items: { type: "string" },
            description:
              "Filter by transaction IDs (primary identifier for withdrawals). A bare numeric ID may be a withdrawal_id (esp. KRW, where uuids and txids are both numeric) — if this returns an empty array, retry the same value via withdrawal_ids before concluding 'not found'.",
          },
          limit: {
            type: "number",
            description: "Number of results per page (max 100)",
          },
          page: {
            type: "number",
            description: "Page number",
          },
          order_by: {
            type: "string",
            enum: ["asc", "desc"],
            description: "Sort order (default: desc)",
          },
        },
        required: [],
      },
      handler: async (rawArgs, context) => {
        const args = asRecord(rawArgs);
        // Exposed param is `withdrawal_ids`, mapped to the API's legacy `uuids`.
        const response = await context.client.privateGet(
          "/v1/withdraws",
          compactObject({
            currency: readString(args, "currency"),
            state: readString(args, "state"),
            uuids: readStringArray(args, "withdrawal_ids"),
            txids: readStringArray(args, "txids"),
            limit: readNumber(args, "limit"),
            page: readNumber(args, "page"),
            order_by: readString(args, "order_by"),
          }),
          privateRateLimit("withdraw_get_list"),
        );
        return normalizeResponse(response);
      },
    },

    // ── 12. withdraw_get_list_krw ────────────────────────────────────
    {
      name: "withdraw_get_list_krw",
      module: "withdraw",
      description:
        "원화 출금 리스트를 조회합니다. Get list of KRW withdrawals. " +
        "Use when: user asks 'recent KRW withdrawals' / filter by state or withdrawal_id. " +
        "식별자 폴백(중요): 입·출금은 txid를 1차 식별자로 쓴다. KRW의 txids와 withdrawal_ids(uuids)는 둘 다 숫자라 값만으로 구분되지 않으므로, 사용자가 맨 숫자 ID를 주면 txids로 먼저 조회 → 빈 배열이면 같은 값을 withdrawal_ids로 재시도(또는 사용자에게 withdrawal_ids로 조회할지 질문)한 뒤에 '없음'으로 단정하라. Both txids and withdrawal_ids are numeric for KRW, so a bare number is ambiguous — if the txids filter returns an empty array, retry the same values via withdrawal_ids (or ask the user) before concluding 'not found'. " +
        'Example call: {"state":"DONE","limit":10}. For a bare numeric ID, try {"txids":["55955615"]} first; if it returns [], retry {"withdrawal_ids":["43007582"]}.',
      isWrite: false,
      inputSchema: {
        type: "object",
        properties: {
          state: {
            type: "string",
            enum: ["PROCESSING", "DONE", "CANCELLED"],
            description: "Withdrawal state filter",
          },
          withdrawal_ids: {
            type: "array",
            items: { type: "string" },
            description:
              "Filter by withdrawal IDs (uuids). Fallback identifier: if a txids lookup returned an empty array for a bare numeric ID, retry that value here (KRW uuids and txids are both numeric, so the value is ambiguous).",
          },
          txids: {
            type: "array",
            items: { type: "string" },
            description:
              "Filter by transaction IDs (primary identifier for withdrawals). A bare numeric ID may be a withdrawal_id (esp. KRW, where uuids and txids are both numeric) — if this returns an empty array, retry the same value via withdrawal_ids before concluding 'not found'.",
          },
          limit: {
            type: "number",
            description: "Number of results per page (max 100)",
          },
          page: {
            type: "number",
            description: "Page number",
          },
          order_by: {
            type: "string",
            enum: ["asc", "desc"],
            description: "Sort order (default: desc)",
          },
        },
        required: [],
      },
      handler: async (rawArgs, context) => {
        const args = asRecord(rawArgs);
        // Exposed param is `withdrawal_ids`, mapped to the API's legacy `uuids`.
        const response = await context.client.privateGet(
          "/v1/withdraws/krw",
          compactObject({
            state: readString(args, "state"),
            uuids: readStringArray(args, "withdrawal_ids"),
            txids: readStringArray(args, "txids"),
            limit: readNumber(args, "limit"),
            page: readNumber(args, "page"),
            order_by: readString(args, "order_by"),
          }),
          privateRateLimit("withdraw_get_list_krw"),
        );
        return normalizeResponse(response);
      },
    },

    // ── 13. withdraw_coin ────────────────────────────────────────────
    {
      name: "withdraw_coin",
      module: "withdraw",
      description:
        "실제 가상 자산을 출금합니다. 이 작업은 되돌릴 수 없습니다. Withdraw cryptocurrency. This action is IRREVERSIBLE. " +
        "Use when: user has explicitly approved a withdrawal AND the full pre-flight checklist has run (account_get_assets, account_get_wallet_status, withdraw_get_chance, withdraw_get_addresses, market_get_fee_inout). " +
        "Do NOT use: without prior `withdraw_get_chance` to confirm net_type/min/fee; without `withdraw_get_addresses` to confirm destination is in the allow-list; without explicit user confirmation of the full destination string. " +
        "Multi-network coins (USDT/USDC/XRP): always run `withdraw_get_chance` first to discover supported `net_type`. Wrong net_type = permanent loss. " +
        "secondary_address (memo/tag): mandatory for XRP/EOS/ATOM-class coins. Missing it = lost funds. " +
        "Withdrawal types: internal member-to-member withdrawals do not need exchange_name; external withdrawals (CODE ID Connect, CODE personal, CODE corporation, WHITELIST) require exchange_name. " +
        "CLI-first: when the Bithumb CLI is installed, prefer the documented `bithumb ...` CLI command for this write operation; use this MCP tool as fallback when the CLI is unavailable/fails or the user explicitly asks for MCP.",
      isWrite: true,
      inputSchema: {
        type: "object",
        properties: {
          currency: {
            type: "string",
            description: "Currency symbol, e.g. BTC",
          },
          net_type: {
            type: "string",
            description: "Withdrawal network, e.g. BTC, DASH",
          },
          amount: {
            type: "string",
            description: "Withdrawal amount",
          },
          address: {
            type: "string",
            description: "Registered withdrawal address",
          },
          secondary_address: {
            type: "string",
            description:
              "Secondary address / memo / tag. Required when the asset/network requires a secondary destination identifier (for example XRP Destination Tag), regardless of withdrawal type.",
          },
          exchange_name: {
            type: "string",
            description:
              "Destination exchange/wallet name (English). Required for external withdrawal types: CODE ID Connect, CODE personal, CODE corporation, WHITELIST. Do not send for internal member-to-member withdrawals. By itself it does NOT trigger receiver-info validation — the trigger is receiver_type.",
          },
          receiver_type: {
            type: "string",
            enum: ["personal", "corporation"],
            description:
              "Receiver type: personal or corporation. Use only for CODE personal/corporation withdrawals; omit for internal, CODE ID Connect, and WHITELIST.",
          },
          receiver_ko_name: {
            type: "string",
            description:
              "Receiver Korean name. personal: 개인 국문명; corporation: 대표자 국문명 (required for both when receiver_type is set)",
          },
          receiver_en_name: {
            type: "string",
            description:
              "Receiver English name. personal: 개인 영문명; corporation: 대표자 영문명 (required for both when receiver_type is set)",
          },
          receiver_corp_ko_name: {
            type: "string",
            description: "Corporation Korean name (required if corporation)",
          },
          receiver_corp_en_name: {
            type: "string",
            description: "Corporation English name (required if corporation)",
          },
        },
        required: ["currency", "net_type", "amount", "address"],
      },
      handler: async (rawArgs, context) => {
        const args = asRecord(rawArgs);

        // 가이드-위임 원칙의 예외: 라우팅·의도 판단은 스킬/MCP 가이드에 위임하지만,
        // 트래블룰 수취인 정보 완결성은 빗썸 POST 직전 코어에서 사전 차단한다.
        // 트리거는 receiver_type 존재 여부다. exchange_name만으로는 출금 타입
        // (내부/CODE ID Connect/CODE/WHITELIST)을 결정론적으로 구분할 수 없고,
        // exchange_name이 있어도 수취인 정보가 불필요한 타입(CODE ID Connect, WHITELIST)이
        // 있으므로 트리거로 쓰지 않는다. receiver_type이 없으면 검증을 건너뛴다
        // (내부 출금·CODE ID Connect·WHITELIST 통과). 있으면 호출자가 수취인 정보를
        // 보내겠다고 명시한 것이므로 그 type의 필드 완결성만 검증한다.
        const receiverType = readString(args, "receiver_type");
        if (
          receiverType !== undefined &&
          receiverType !== "personal" &&
          receiverType !== "corporation"
        ) {
          throw new ValidationError(
            `Invalid receiver_type: ${receiverType}.`,
            "receiver_type only accepts the lowercase strings 'personal' or 'corporation'.",
          );
        }
        if (receiverType === "personal") {
          const missing = (
            ["receiver_ko_name", "receiver_en_name"] as const
          ).filter((field) => !readString(args, field));
          if (missing.length > 0) {
            throw new ValidationError(
              `Missing required receiver info for personal receiver: ${missing.join(", ")}.`,
              "Travel Rule requires both receiver_ko_name (국문 성명) and receiver_en_name (영문 성명) when receiver_type is personal.",
            );
          }
        } else if (receiverType === "corporation") {
          const missing = (
            [
              "receiver_corp_ko_name",
              "receiver_corp_en_name",
              "receiver_ko_name",
              "receiver_en_name",
            ] as const
          ).filter((field) => !readString(args, field));
          if (missing.length > 0) {
            throw new ValidationError(
              `Missing required receiver info for corporation receiver: ${missing.join(", ")}.`,
              "Travel Rule requires corporation name (receiver_corp_ko_name/receiver_corp_en_name) and representative name (receiver_ko_name/receiver_en_name) when receiver_type is corporation.",
            );
          }
        }

        const response = await context.client.privatePost(
          "/v1/withdraws/coin",
          compactObject({
            currency: requireString(args, "currency"),
            net_type: requireString(args, "net_type"),
            amount: requireString(args, "amount"),
            address: requireString(args, "address"),
            secondary_address: readString(args, "secondary_address"),
            exchange_name: readString(args, "exchange_name"),
            receiver_type: readString(args, "receiver_type"),
            receiver_ko_name: readString(args, "receiver_ko_name"),
            receiver_en_name: readString(args, "receiver_en_name"),
            receiver_corp_ko_name: readString(args, "receiver_corp_ko_name"),
            receiver_corp_en_name: readString(args, "receiver_corp_en_name"),
          }),
          orderRateLimit("withdraw_coin"),
        );
        return normalizeResponse(response);
      },
    },

    // ── 14. withdraw_krw ─────────────────────────────────────────────
    {
      name: "withdraw_krw",
      module: "withdraw",
      description:
        "등록된 계좌로 원화를 출금합니다. 이 작업은 되돌릴 수 없습니다. 2차 인증(카카오)이 필요합니다. Withdraw KRW to registered bank account. This action is IRREVERSIBLE. Requires 2FA (Kakao). " +
        "⚠️ REQUIRES EXPLICIT USER CONFIRMATION before executing: show the user the withdrawal amount and wait for explicit approval. Do NOT withdraw without user confirmation. " +
        "CLI-first: when the Bithumb CLI is installed, prefer the documented `bithumb ...` CLI command for this write operation; use this MCP tool as fallback when the CLI is unavailable/fails or the user explicitly asks for MCP.",
      isWrite: true,
      inputSchema: {
        type: "object",
        properties: {
          amount: {
            type: "string",
            description: "Withdrawal amount in KRW",
          },
          two_factor_type: {
            type: "string",
            description: "2FA method (e.g. kakao)",
          },
        },
        required: ["amount", "two_factor_type"],
      },
      handler: async (rawArgs, context) => {
        const args = asRecord(rawArgs);
        const response = await context.client.privatePost(
          "/v1/withdraws/krw",
          {
            amount: requireString(args, "amount"),
            two_factor_type: requireString(args, "two_factor_type"),
          },
          orderRateLimit("withdraw_krw"),
        );
        return normalizeResponse(response);
      },
    },

    // ── 15. withdraw_cancel_coin ─────────────────────────────────────
    {
      name: "withdraw_cancel_coin",
      module: "withdraw",
      description:
        "가상 자산 출금을 취소합니다. Cancel a cryptocurrency withdrawal. " +
        "⚠️ REQUIRES EXPLICIT USER CONFIRMATION before executing: show the user the withdrawal ID and wait for explicit approval. Do NOT cancel without user confirmation. " +
        "CLI-first: when the Bithumb CLI is installed, prefer the documented `bithumb ...` CLI command for this write operation; use this MCP tool as fallback when the CLI is unavailable/fails or the user explicitly asks for MCP.",
      isWrite: true,
      inputSchema: {
        type: "object",
        properties: {
          withdrawal_id: {
            type: "string",
            description: "Withdrawal unique ID to cancel",
          },
        },
        required: ["withdrawal_id"],
      },
      handler: async (rawArgs, context) => {
        const args = asRecord(rawArgs);
        const response = await context.client.privateDelete(
          "/v1/withdraws/coin",
          {
            withdrawal_id: requireString(args, "withdrawal_id"),
          },
          orderRateLimit("withdraw_cancel_coin"),
        );
        return normalizeResponse(response);
      },
    },

    // ── 16. withdraw_get_addresses ───────────────────────────────────
    {
      name: "withdraw_get_addresses",
      module: "withdraw",
      description:
        "출금 허용 주소 리스트를 조회합니다. Get list of allowed withdrawal addresses.",
      isWrite: false,
      inputSchema: {
        type: "object",
        properties: {},
        required: [],
      },
      handler: async (_rawArgs, context) => {
        const response = await context.client.privateGet(
          "/v1/withdraws/coin_addresses",
          {},
          privateRateLimit("withdraw_get_addresses"),
        );
        return normalizeResponse(response);
      },
    },
  ];
}
