// ─── Tool Argument Helpers ─────────────────────────────────────────

import { ValidationError } from "../utils/errors.js";

export type ArgsRecord = Record<string, unknown>;

/** Safely cast args to Record. */
export function asRecord(args: unknown): ArgsRecord {
  if (args && typeof args === "object" && !Array.isArray(args)) {
    return args as ArgsRecord;
  }
  return {};
}

// ─── Read helpers (return undefined if missing) ────────────────────

export function readString(
  args: ArgsRecord,
  key: string,
): string | undefined {
  const v = args[key];
  if (v === undefined || v === null || v === "") return undefined;
  return String(v);
}

export function readNumber(
  args: ArgsRecord,
  key: string,
): number | undefined {
  const v = args[key];
  if (v === undefined || v === null || v === "") return undefined;
  const n = Number(v);
  if (!Number.isFinite(n)) return undefined;
  return n;
}

export function readBoolean(
  args: ArgsRecord,
  key: string,
): boolean | undefined {
  const v = args[key];
  if (v === undefined || v === null) return undefined;
  if (typeof v === "boolean") return v;
  if (v === "true" || v === "1") return true;
  if (v === "false" || v === "0") return false;
  return undefined;
}

export function readStringArray(
  args: ArgsRecord,
  key: string,
): string[] | undefined {
  const v = args[key];
  if (v === undefined || v === null) return undefined;
  if (Array.isArray(v)) return v.map(String);
  if (typeof v === "string") {
    return v
      .split(",")
      .map((s) => s.trim())
      .filter(Boolean);
  }
  return undefined;
}

// ─── Require helpers (throw on missing) ────────────────────────────

export function requireString(
  args: ArgsRecord,
  key: string,
): string {
  const v = readString(args, key);
  if (!v) {
    throw new ValidationError(
      `Missing required parameter "${key}".`,
      `Provide a non-empty "${key}" string.`,
    );
  }
  return v;
}

export function assertEnum<T extends string>(
  value: string,
  allowed: readonly T[],
  paramName: string,
): T {
  if (!allowed.includes(value as T)) {
    throw new ValidationError(
      `Invalid value "${value}" for "${paramName}".`,
      `Allowed: ${allowed.join(", ")}.`,
    );
  }
  return value as T;
}

// ─── Misc utilities ────────────────────────────────────────────────

/** Remove undefined/null entries from an object. */
export function compactObject<T extends Record<string, unknown>>(
  obj: T,
): Partial<T> {
  const result: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(obj)) {
    if (value !== undefined && value !== null) {
      result[key] = value;
    }
  }
  return result as Partial<T>;
}

/** Normalize tool response into a consistent shape. */
export function normalizeResponse(data: unknown): unknown {
  if (data === null || data === undefined) return {};
  return data;
}
