// ─── Trade Logger ──────────────────────────────────────────────────

import { mkdirSync, appendFileSync, chmodSync, existsSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";

export type LogLevel = "debug" | "info" | "warn" | "error";

export interface LogEntry {
  ts: string;
  level: LogLevel;
  tool?: string;
  endpoint?: string;
  elapsed?: number;
  message: string;
  [key: string]: unknown;
}

const LEVEL_ORDER: Record<LogLevel, number> = {
  debug: 0,
  info: 1,
  warn: 2,
  error: 3,
};

const SENSITIVE_KEY_PATTERN =
  /accessKey|secretKey|password|secret|token|jwt/i;

function redactSensitive(obj: Record<string, unknown>): Record<string, unknown> {
  const result: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(obj)) {
    if (SENSITIVE_KEY_PATTERN.test(key)) {
      result[key] = "***REDACTED***";
    } else if (value && typeof value === "object" && !Array.isArray(value)) {
      result[key] = redactSensitive(value as Record<string, unknown>);
    } else {
      result[key] = value;
    }
  }
  return result;
}

function todayDateString(): string {
  const d = new Date();
  const yyyy = d.getFullYear();
  const mm = String(d.getMonth() + 1).padStart(2, "0");
  const dd = String(d.getDate()).padStart(2, "0");
  return `${yyyy}-${mm}-${dd}`;
}

export class TradeLogger {
  private readonly logDir: string;
  private readonly minLevel: LogLevel;
  private readonly verbose: boolean;
  private readonly emitToStderr: boolean;

  constructor(minLevelOrOptions?: LogLevel | { logDir?: string; minLevel?: LogLevel; verbose?: boolean; emitToStderr?: boolean }) {
    if (typeof minLevelOrOptions === "string") {
      this.logDir = join(homedir(), ".bithumb", "logs");
      this.minLevel = minLevelOrOptions;
      this.verbose = false;
      this.emitToStderr = true;
    } else {
      this.logDir = minLevelOrOptions?.logDir ?? join(homedir(), ".bithumb", "logs");
      this.minLevel = minLevelOrOptions?.minLevel ?? "info";
      this.verbose = minLevelOrOptions?.verbose ?? false;
      this.emitToStderr = minLevelOrOptions?.emitToStderr ?? true;
    }

    try {
      // Logs may contain withdrawal addresses, receiver names, and amounts, so
      // the directory must be owner-only.
      mkdirSync(this.logDir, { recursive: true, mode: 0o700 });
    } catch {
      // Silently ignore if directory cannot be created
    }
  }

  debug(message: string, meta?: Record<string, unknown>): void {
    this.log("debug", message, meta);
  }

  info(message: string, meta?: Record<string, unknown>): void {
    this.log("info", message, meta);
  }

  warn(message: string, meta?: Record<string, unknown>): void {
    this.log("warn", message, meta);
  }

  error(message: string, meta?: Record<string, unknown>): void {
    this.log("error", message, meta);
  }

  /** Log a tool invocation result (used by MCP server). */
  logTool(
    level: LogLevel,
    toolName: string,
    args: unknown,
    result: unknown,
    elapsedMs: number,
  ): void {
    this.log(level, `tool:${toolName}`, {
      args: args as Record<string, unknown>,
      result: result as Record<string, unknown>,
      elapsedMs,
    });
  }

  private log(level: LogLevel, message: string, meta?: Record<string, unknown>): void {
    if (LEVEL_ORDER[level] < LEVEL_ORDER[this.minLevel]) return;

    const entry: LogEntry = {
      ts: new Date().toISOString(),
      level,
      message,
      ...(meta ? redactSensitive(meta) : {}),
    };

    const line = JSON.stringify(entry);

    if (this.emitToStderr && (this.verbose || level === "error")) {
      process.stderr.write(`[${level}] ${message}\n`);
    }

    try {
      const filePath = join(this.logDir, `trade-${todayDateString()}.log`);
      const existed = existsSync(filePath);
      appendFileSync(filePath, line + "\n", { encoding: "utf8", mode: 0o600 });
      // appendFileSync's mode only applies on creation; tighten a pre-existing
      // file the first time we touch it this run.
      if (!existed) chmodSync(filePath, 0o600);
    } catch {
      // Silently ignore file write errors
    }
  }
}
