// ─── Bithumb JWT HS256 Authentication ──────────────────────────────

import { createHash, createHmac, randomUUID } from "node:crypto";

function base64url(input: string | Buffer): string {
  const buf = typeof input === "string" ? Buffer.from(input) : input;
  return buf.toString("base64url");
}

/**
 * SHA-512 hash of query string for JWT payload.
 */
export function hashQuery(queryString: string): string {
  return createHash("sha512").update(queryString, "utf8").digest("hex");
}

export interface JwtPayload {
  access_key: string;
  nonce: string;
  timestamp: number;
  query_hash?: string;
  query_hash_alg?: string;
}

/**
 * Create a JWT token with HS256 signing (manual implementation, no deps).
 */
export function createJwt(payload: JwtPayload, secretKey: string): string {
  const header = { alg: "HS256", typ: "JWT" };
  const headerB64 = base64url(JSON.stringify(header));
  const payloadB64 = base64url(JSON.stringify(payload));
  const signature = createHmac("sha256", secretKey)
    .update(`${headerB64}.${payloadB64}`)
    .digest("base64url");
  return `${headerB64}.${payloadB64}.${signature}`;
}

/**
 * Build a signed JWT Bearer token for Bithumb API v2.1.5.
 *
 * @param accessKey - BITHUMB_ACCESS_KEY
 * @param secretKey - BITHUMB_SECRET_KEY
 * @param queryString - Optional query/body string to hash (key=value&key=value)
 */
export function signRequest(
  accessKey: string,
  secretKey: string,
  queryString?: string,
): string {
  const payload: JwtPayload = {
    access_key: accessKey,
    nonce: randomUUID(),
    timestamp: Date.now(),
  };

  if (queryString && queryString.length > 0) {
    payload.query_hash = hashQuery(queryString);
    payload.query_hash_alg = "SHA512";
  }

  return createJwt(payload, secretKey);
}
