// ─── Configuration ─────────────────────────────────────────────────

import {
  BITHUMB_API_BASE_URL,
  DEFAULT_MODULES,
  MODULES,
  type ModuleId,
  type ClientType,
} from "./constants.js";
import { ConfigError } from "./utils/errors.js";
import { readTomlProfile } from "./config/toml.js";
import { validateTimeoutMs } from "./config/validation.js";

export interface BithumbConfig {
  accessKey?: string;
  secretKey?: string;
  hasAuth: boolean;
  baseUrl: string;
  timeoutMs: number;
  modules: ModuleId[];
  readOnly: boolean;
  verbose: boolean;
  clientType: ClientType;
}

export function loadConfig(options?: {
  modules?: string;
  readOnly?: boolean;
  verbose?: boolean;
  profile?: string;
  clientType?: ClientType;
  ignoreToml?: boolean;
}): BithumbConfig {
  const toml = options?.ignoreToml ? {} : readTomlProfile(options?.profile);

  // Credential precedence:
  //   --profile explicit → toml(profile) > env  (the typed --profile is a
  //     deliberate "run as this account" selector; for a trading tool, a stale
  //     env key silently overriding it could route orders to the wrong account)
  //   --profile omitted  → env > toml(default_profile)  (env is a temporary
  //     override of the stored default)
  // The access/secret pair is resolved as a unit (all-or-nothing per source):
  // a source only "wins" if it supplies BOTH keys. This prevents pairing one
  // account's access_key with another account's secret_key — the most
  // dangerous failure mode for a trading tool, which per-key fallback allowed.
  // Scope: credentials only. base_url/timeout_ms keep env-first below.
  const profileExplicit = options?.profile !== undefined;
  const envAccessKey = process.env.BITHUMB_ACCESS_KEY?.trim();
  const envSecretKey = process.env.BITHUMB_SECRET_KEY?.trim();
  const tomlComplete = Boolean(toml.access_key && toml.secret_key);
  const envComplete = Boolean(envAccessKey && envSecretKey);
  const preferToml = profileExplicit ? tomlComplete : !envComplete;
  const accessKey = preferToml ? toml.access_key : envAccessKey;
  const secretKey = preferToml ? toml.secret_key : envSecretKey;
  const hasAuth = Boolean(accessKey && secretKey);
  // Partial when credential material exists in any source but no single source
  // supplied a complete pair (covers a dangling env key, a dangling toml key,
  // and the cross-source split that all-or-nothing deliberately refuses to pair).
  const anyKeyPresent =
    Boolean(envAccessKey || envSecretKey || toml.access_key || toml.secret_key);

  if (anyKeyPresent && !hasAuth) {
    throw new ConfigError(
      "Partial API credentials.",
      "Set both BITHUMB_ACCESS_KEY and BITHUMB_SECRET_KEY (env vars or config.toml profile).",
    );
  }

  const baseUrl = (
    process.env.BITHUMB_API_BASE_URL?.trim() ?? toml.base_url ?? BITHUMB_API_BASE_URL
  ).replace(/\/+$/, "");

  const rawTimeout = process.env.BITHUMB_TIMEOUT_MS
    ? Number(process.env.BITHUMB_TIMEOUT_MS)
    : (toml.timeout_ms ?? 30_000);

  // Same rule as the CLI write surface (ADR 0013): read and write agree.
  const timeoutMs = validateTimeoutMs(rawTimeout);

  // Parse modules
  let modules: ModuleId[] = [...DEFAULT_MODULES];
  if (options?.modules) {
    const requested = options.modules
      .split(",")
      .map((s) => s.trim())
      .filter(Boolean);

    if (requested.length > 0) {
      let isAll = false;
      for (const m of requested) {
        if (m === "all") {
          modules = [...MODULES];
          isAll = true;
          break;
        }
        if (!MODULES.includes(m as ModuleId)) {
          throw new ConfigError(
            `Unknown module "${m}".`,
            `Use: ${MODULES.join(", ")} or "all".`,
          );
        }
      }
      if (!isAll) modules = requested as ModuleId[];
    }
  }

  if (toml.read_only !== undefined && typeof toml.read_only !== "boolean") {
    throw new ConfigError(
      "Invalid read_only.",
      "config.toml profile read_only must be a boolean (true or false), not a string or number.",
    );
  }

  return {
    accessKey,
    secretKey,
    hasAuth,
    baseUrl,
    timeoutMs,
    modules,
    readOnly: options?.readOnly ?? toml.read_only ?? false,
    verbose: options?.verbose ?? false,
    clientType: options?.clientType ?? "etc",
  };
}
