// ─── Account Tools (Private) ───────────────────────────────────────

import type { ToolSpec } from "./types.js";
import {
  asRecord,
  compactObject,
  normalizeResponse,
  requireString,
} from "./helpers.js";
import { privateRateLimit } from "./common.js";

export function registerAccountTools(): ToolSpec[] {
  return [
    // ── 1. account_get_assets ──────────────────────────────────────
    {
      name: "account_get_assets",
      module: "account",
      description:
        "전체 계좌 잔고를 조회합니다. Get all account balances. " +
        "Returns all currencies with balance, locked amounts, and avg buy price. " +
        "Run before any trade or withdrawal to verify available funds.",
      isWrite: false,
      inputSchema: {
        type: "object",
        properties: {},
        required: [],
      },
      handler: async (_rawArgs, context) => {
        const response = await context.client.privateGet(
          "/v1/accounts",
          undefined,
          privateRateLimit("account_get_assets"),
        );
        return normalizeResponse(response);
      },
    },

    // ── 2. account_get_order_chance ────────────────────────────────
    {
      name: "account_get_order_chance",
      module: "account",
      description:
        "주문 가능 정보를 조회합니다. Get order chance info (available balance, fees, limits) for a market. " +
        "Run before placing any order to confirm available balance, bid/ask fee rates, and min/max order size constraints.",
      isWrite: false,
      inputSchema: {
        type: "object",
        properties: {
          market: {
            type: "string",
            description: "Market code, e.g. KRW-BTC",
          },
        },
        required: ["market"],
      },
      handler: async (rawArgs, context) => {
        const args = asRecord(rawArgs);
        const response = await context.client.privateGet(
          "/v1/orders/chance",
          compactObject({ market: requireString(args, "market") }),
          privateRateLimit("account_get_order_chance"),
        );
        return normalizeResponse(response);
      },
    },

    // ── 3. account_get_wallet_status ───────────────────────────────
    {
      name: "account_get_wallet_status",
      module: "account",
      description:
        "입출금 현황을 조회합니다. Get wallet status (block status, deposit/withdrawal availability). " +
        "Run before any deposit or withdrawal to verify the blockchain is synced and operations are not disabled for maintenance.",
      isWrite: false,
      inputSchema: {
        type: "object",
        properties: {},
        required: [],
      },
      handler: async (_rawArgs, context) => {
        const response = await context.client.privateGet(
          "/v1/status/wallet",
          {},
          privateRateLimit("account_get_wallet_status"),
        );
        return normalizeResponse(response);
      },
    },

    // ── 4. account_get_api_keys ────────────────────────────────────
    {
      name: "account_get_api_keys",
      module: "account",
      description:
        "API 키 목록을 조회합니다. Get list of API keys and expiration dates. " +
        "Check periodically to avoid unexpected authentication failures due to key expiration.",
      isWrite: false,
      inputSchema: {
        type: "object",
        properties: {},
        required: [],
      },
      handler: async (_rawArgs, context) => {
        const response = await context.client.privateGet(
          "/v1/api_keys",
          {},
          privateRateLimit("account_get_api_keys"),
        );
        return normalizeResponse(response);
      },
    },
  ];
}
