// ─── Common Rate Limit Presets ─────────────────────────────────────

import type { RateLimitConfig } from "../utils/rate-limiter.js";

/** Public endpoint: 150 requests/sec default. */
export function publicRateLimit(key: string, rps = 150): RateLimitConfig {
  return { key: `public:${key}`, capacity: rps, refillPerSecond: rps };
}

/** Private endpoint: 140 requests/sec default. */
export function privateRateLimit(key: string, rps = 140): RateLimitConfig {
  return { key: `private:${key}`, capacity: rps, refillPerSecond: rps };
}

/** Order endpoint: 10 requests/sec default. */
export function orderRateLimit(key: string, rps = 10): RateLimitConfig {
  return { key: `order:${key}`, capacity: rps, refillPerSecond: rps };
}
