// ─── Token-Bucket Rate Limiter ─────────────────────────────────────

import { RateLimitError } from "./errors.js";

export interface RateLimitConfig {
  /** Unique key for this bucket (e.g. "public:markets") */
  key: string;
  /** Maximum burst capacity */
  capacity: number;
  /** Tokens restored per second */
  refillPerSecond: number;
}

interface Bucket {
  tokens: number;
  capacity: number;
  refillPerSecond: number;
  lastRefill: number;
}

export class RateLimiter {
  private readonly buckets = new Map<string, Bucket>();
  private readonly cleanupMs: number;
  private readonly verbose: boolean;
  private lastCleanup: number;

  constructor(cleanupMs = 30_000, verbose = false) {
    this.cleanupMs = cleanupMs;
    this.verbose = verbose;
    this.lastCleanup = Date.now();
  }

  async consume(config: RateLimitConfig, amount = 1): Promise<void> {
    this.maybeCleanup();
    const bucket = this.getBucket(config);
    this.refill(bucket);

    if (bucket.tokens >= amount) {
      bucket.tokens -= amount;
      return;
    }

    // Wait for tokens to refill
    const deficit = amount - bucket.tokens;
    const waitMs = Math.ceil((deficit / bucket.refillPerSecond) * 1_000);

    if (waitMs > 10_000) {
      throw new RateLimitError(
        `Rate limit exceeded for "${config.key}". Need ${deficit.toFixed(1)} tokens, wait ~${waitMs}ms.`,
        "Reduce request frequency or wait.",
      );
    }

    if (this.verbose) {
      process.stderr.write(
        `[rate-limiter] ${config.key}: waiting ${waitMs}ms for ${deficit.toFixed(1)} tokens\n`,
      );
    }

    await new Promise((resolve) => setTimeout(resolve, waitMs));
    this.refill(bucket);

    if (bucket.tokens >= amount) {
      bucket.tokens -= amount;
      return;
    }

    throw new RateLimitError(
      `Rate limit exceeded for "${config.key}" after waiting.`,
      "Reduce request frequency.",
    );
  }

  private getBucket(config: RateLimitConfig): Bucket {
    let bucket = this.buckets.get(config.key);
    if (!bucket) {
      bucket = {
        tokens: config.capacity,
        capacity: config.capacity,
        refillPerSecond: config.refillPerSecond,
        lastRefill: Date.now(),
      };
      this.buckets.set(config.key, bucket);
    }
    return bucket;
  }

  private refill(bucket: Bucket): void {
    const now = Date.now();
    const elapsed = (now - bucket.lastRefill) / 1_000;
    if (elapsed <= 0) return;
    bucket.tokens = Math.min(
      bucket.capacity,
      bucket.tokens + elapsed * bucket.refillPerSecond,
    );
    bucket.lastRefill = now;
  }

  private maybeCleanup(): void {
    const now = Date.now();
    if (now - this.lastCleanup < this.cleanupMs) return;
    this.lastCleanup = now;

    for (const [key, bucket] of this.buckets) {
      const idle = (now - bucket.lastRefill) / 1_000;
      if (idle > 60 && bucket.tokens >= bucket.capacity) {
        this.buckets.delete(key);
      }
    }
  }
}
