// ─── Deposit Tools (Private) ──────────────────────────────────────

import type { ToolSpec } from "./types.js";
import {
  asRecord,
  compactObject,
  normalizeResponse,
  readNumber,
  readString,
  readStringArray,
  requireString,
} from "./helpers.js";
import { privateRateLimit } from "./common.js";

export function registerDepositTools(): ToolSpec[] {
  return [
    // ── 17. deposit_get ───────────────────────────────────────────
    {
      name: "deposit_get",
      module: "deposit",
      description:
        "식별자(txid 또는 deposit_id) 1개로 특정 입금 1건을 조회합니다. 단건 조회의 canonical 도구. " +
        "Single deposit by one identifier. " +
        "Use when: you have one txid or deposit_id. " +
        "Do NOT use: to search by state or multiple txids — use deposit_get_list instead. " +
        "식별자 폴백(중요): 입·출금은 txid를 1차 식별자로 쓴다. 맨 숫자 ID는 txid인지 deposit_id인지 값만으로 구분되지 않으므로(KRW뿐 아니라 코인도 deposit_id가 숫자일 수 있음), txid로 먼저 조회 → deposit_not_found면 같은 값을 deposit_id로 재시도한 뒤에 '없음'으로 단정하라. A bare numeric ID is ambiguous (txid and deposit_id can both be numeric, even for coins) — query txid first; on deposit_not_found, retry the same value as deposit_id before concluding 'not found'. " +
        'Example call: {"currency":"BTC","txid":"2025-07-31 15:12:24.407715"}. For a bare numeric ID, try {"currency":"TRX","txid":"719812240"} first; on deposit_not_found, retry {"currency":"TRX","deposit_id":"719812240"}.',
      isWrite: false,
      inputSchema: {
        type: "object",
        properties: {
          currency: {
            type: "string",
            description: "Currency symbol, e.g. BTC",
          },
          deposit_id: {
            type: "string",
            description: "Deposit ID",
          },
          txid: {
            type: "string",
            description: "Deposit TXID",
          },
        },
        required: ["currency"],
      },
      handler: async (rawArgs, context) => {
        const args = asRecord(rawArgs);
        // Exposed param is `deposit_id`, but the Bithumb GET /v1/deposit endpoint
        // expects it in the `uuid` field (legacy naming — the "uuid" is actually
        // the deposit_id).
        const response = await context.client.privateGet(
          "/v1/deposit",
          compactObject({
            currency: requireString(args, "currency"),
            uuid: readString(args, "deposit_id"),
            txid: readString(args, "txid"),
          }),
          privateRateLimit("deposit_get"),
        );
        return normalizeResponse(response);
      },
    },

    // ── 18. deposit_get_list ──────────────────────────────────────
    {
      name: "deposit_get_list",
      module: "deposit",
      description:
        "여러 입금을 검색하거나 상태로 거른 리스트를 조회합니다. 식별자가 1개뿐이면 deposit_get(단건)을 쓰세요. " +
        "List of coin deposits (table-rendered; same fields as deposit_get). " +
        "Use when: 'recent deposits' / filter by state / search across multiple txids. " +
        "Do NOT use: when you have a single deposit_id or txid — use deposit_get instead. " +
        "식별자 폴백(리스트 검색 시): 입·출금은 txid를 1차 식별자로 쓴다. 맨 숫자 ID는 txid인지 deposit_id(deposit_ids)인지 값만으로 구분되지 않으므로(KRW뿐 아니라 코인도 deposit_id가 숫자일 수 있음), 맨 숫자가 주어지면 txids로 먼저 조회 → 빈 배열이면 같은 값을 deposit_ids로 재시도(또는 사용자 질문)한 뒤에 '없음'으로 단정하라. A bare numeric ID is ambiguous (txid and deposit_id can both be numeric, even for coins) — search txids first; if it returns an empty array, retry the same values via deposit_ids (or ask the user) before concluding 'not found'. " +
        "⚠️ 공백·쉼표 포함 txid 제약: 빗썸 목록 엔드포인트의 txids 필터는 값에 공백이나 쉼표가 있으면(올바로 percent-encode해도) 매칭하지 못한다(서버 제약). 그런 txid(예: 'EVENT_COUPON:4,649', '2025-07-31 15:12:24.407715')는 txids로 조회하지 말고 deposit_get 단건(txid)으로 조회하라. A txid containing a space or comma cannot be matched by the list txids filter (server-side limitation, even when correctly encoded) — use the single-record deposit_get with `txid` instead. " +
        'Example call (txid lookup): {"txids":["0xabc123..."]}',
      isWrite: false,
      inputSchema: {
        type: "object",
        properties: {
          currency: {
            type: "string",
            description: "Currency symbol, e.g. BTC",
          },
          state: {
            type: "string",
            enum: [
              "REQUESTED_PENDING",
              "REQUESTED_SYSTEM_REJECTED",
              "REQUESTED_PROCESSING",
              "REQUESTED_ADMIN_REJECTED",
              "DEPOSIT_PROCESSING",
              "DEPOSIT_ACCEPTED",
              "DEPOSIT_CANCELLED",
              "REFUNDING_PENDING",
              "REFUNDING_SYSTEM_REJECTED",
              "REFUNDING_PROCESSING",
              "REFUNDING_ADMIN_REJECTED",
              "REFUNDING_ACCEPTED",
              "REFUNDED_PROCESSING",
              "REFUNDED_ACCEPTED",
              "REFUNDED_CANCELLED",
            ],
            description:
              "Coin deposit state filter (case-sensitive UPPERCASE). " +
              "Covers request / deposit / refund-request / refund-payout phases.",
          },
          deposit_ids: {
            type: "array",
            items: { type: "string" },
            description:
              "Filter by deposit IDs (uuids). Fallback identifier: if a txids lookup returned an empty array for a bare numeric ID, retry that value here (KRW uuids and txids are both numeric, so the value is ambiguous).",
          },
          txids: {
            type: "array",
            items: { type: "string" },
            description:
              "Filter by deposit TXIDs (primary identifier for deposits). A bare numeric ID may be a deposit_id (esp. KRW, where uuids and txids are both numeric) — if this returns an empty array, retry the same value via deposit_ids before concluding 'not found'.",
          },
          limit: {
            type: "number",
            description: "Number of results (max 100)",
          },
          page: {
            type: "number",
            description: "Page number (default 1)",
          },
          order_by: {
            type: "string",
            description: "Sort order: asc or desc (default desc)",
          },
        },
        required: [],
      },
      handler: async (rawArgs, context) => {
        const args = asRecord(rawArgs);
        // Exposed param is `deposit_ids`, mapped to the API's legacy `uuids`.
        const response = await context.client.privateGet(
          "/v1/deposits",
          compactObject({
            currency: readString(args, "currency"),
            state: readString(args, "state"),
            uuids: readStringArray(args, "deposit_ids"),
            txids: readStringArray(args, "txids"),
            limit: readNumber(args, "limit"),
            page: readNumber(args, "page"),
            order_by: readString(args, "order_by"),
          }),
          privateRateLimit("deposit_get_list"),
        );
        return normalizeResponse(response);
      },
    },

    // ── 19. deposit_get_list_krw ──────────────────────────────────
    {
      name: "deposit_get_list_krw",
      module: "deposit",
      description:
        "원화 입금 리스트를 조회합니다. Get list of KRW deposits. " +
        "Use when: user asks 'recent KRW deposits' / filter by state or deposit_id. " +
        "식별자 폴백(중요): 입·출금은 txid를 1차 식별자로 쓴다. KRW의 txids와 deposit_ids(uuids)는 둘 다 숫자라 값만으로 구분되지 않으므로, 사용자가 맨 숫자 ID를 주면 txids로 먼저 조회 → 빈 배열이면 같은 값을 deposit_ids로 재시도(또는 사용자에게 deposit_ids로 조회할지 질문)한 뒤에 '없음'으로 단정하라. Both txids and deposit_ids are numeric for KRW, so a bare number is ambiguous — search txids first; if it returns an empty array, retry the same values via deposit_ids (or ask the user) before concluding 'not found'. " +
        'Example call: {"state":"ACCEPTED","limit":10}. For a bare numeric ID, try {"txids":["1657265"]} first; if it returns [], retry {"deposit_ids":["405896908"]}.',
      isWrite: false,
      inputSchema: {
        type: "object",
        properties: {
          state: {
            type: "string",
            enum: ["PROCESSING", "ACCEPTED", "CANCELLED"],
            description: "Deposit state: PROCESSING, ACCEPTED, CANCELLED",
          },
          deposit_ids: {
            type: "array",
            items: { type: "string" },
            description:
              "Filter by deposit IDs (uuids). Fallback identifier: if a txids lookup returned an empty array for a bare numeric ID, retry that value here (KRW uuids and txids are both numeric, so the value is ambiguous).",
          },
          txids: {
            type: "array",
            items: { type: "string" },
            description:
              "Filter by deposit TXIDs (primary identifier for deposits). A bare numeric ID may be a deposit_id (esp. KRW, where uuids and txids are both numeric) — if this returns an empty array, retry the same value via deposit_ids before concluding 'not found'.",
          },
          limit: {
            type: "number",
            description: "Number of results (max 100)",
          },
          page: {
            type: "number",
            description: "Page number (default 1)",
          },
          order_by: {
            type: "string",
            description: "Sort order: asc or desc (default desc)",
          },
        },
        required: [],
      },
      handler: async (rawArgs, context) => {
        const args = asRecord(rawArgs);
        // Exposed param is `deposit_ids`, mapped to the API's legacy `uuids`.
        const response = await context.client.privateGet(
          "/v1/deposits/krw",
          compactObject({
            state: readString(args, "state"),
            uuids: readStringArray(args, "deposit_ids"),
            txids: readStringArray(args, "txids"),
            limit: readNumber(args, "limit"),
            page: readNumber(args, "page"),
            order_by: readString(args, "order_by"),
          }),
          privateRateLimit("deposit_get_list_krw"),
        );
        return normalizeResponse(response);
      },
    },

    // ── 20. deposit_krw ──────────────────────────────────────────
    {
      name: "deposit_krw",
      module: "deposit",
      description:
        "원화 입금을 요청합니다. 2차 인증(카카오)이 필요합니다. Request KRW deposit. Requires 2FA (Kakao). " +
        "⚠️ REQUIRES EXPLICIT USER CONFIRMATION before executing: show the user the deposit amount and wait for explicit approval. Do NOT request deposit without user confirmation. " +
        "CLI-first: when the Bithumb CLI is installed, prefer the documented `bithumb ...` CLI command for this write operation; use this MCP tool as fallback when the CLI is unavailable/fails or the user explicitly asks for MCP.",
      isWrite: true,
      inputSchema: {
        type: "object",
        properties: {
          amount: {
            type: "string",
            description: "Deposit amount in KRW",
          },
          two_factor_type: {
            type: "string",
            description: "2FA method, e.g. kakao",
          },
        },
        required: ["amount", "two_factor_type"],
      },
      handler: async (rawArgs, context) => {
        const args = asRecord(rawArgs);
        const response = await context.client.privatePost(
          "/v1/deposits/krw",
          {
            amount: requireString(args, "amount"),
            two_factor_type: requireString(args, "two_factor_type"),
          },
          privateRateLimit("deposit_krw"),
        );
        return normalizeResponse(response);
      },
    },

    // ── 21. deposit_generate_address ─────────────────────────────
    {
      name: "deposit_generate_address",
      module: "deposit",
      description:
        "입금 주소를 생성합니다. Generate a new deposit address. " +
        "⚠️ REQUIRES EXPLICIT USER CONFIRMATION before executing: show the user the currency and network type, then wait for explicit approval. Do NOT generate without user confirmation. " +
        "CLI-first: when the Bithumb CLI is installed, prefer the documented `bithumb ...` CLI command for this write operation; use this MCP tool as fallback when the CLI is unavailable/fails or the user explicitly asks for MCP.",
      isWrite: true,
      inputSchema: {
        type: "object",
        properties: {
          currency: {
            type: "string",
            description: "Currency symbol, e.g. BTC",
          },
          net_type: {
            type: "string",
            description: "Network type, e.g. BTC, ETH",
          },
        },
        required: ["currency", "net_type"],
      },
      handler: async (rawArgs, context) => {
        const args = asRecord(rawArgs);
        const response = await context.client.privatePost(
          "/v1/deposits/generate_coin_address",
          {
            currency: requireString(args, "currency"),
            net_type: requireString(args, "net_type"),
          },
          privateRateLimit("deposit_generate_address"),
        );
        return normalizeResponse(response);
      },
    },

    // ── 22. deposit_get_addresses ────────────────────────────────
    {
      name: "deposit_get_addresses",
      module: "deposit",
      description:
        "전체 입금 주소를 조회합니다. Get all deposit addresses. " +
        "Use this first for multi-network coins (USDT, USDC, XRP, etc.) to discover available currency + net_type combinations before calling deposit_get_address.",
      isWrite: false,
      inputSchema: {
        type: "object",
        properties: {},
        required: [],
      },
      handler: async (_rawArgs, context) => {
        const response = await context.client.privateGet(
          "/v1/deposits/coin_addresses",
          {},
          privateRateLimit("deposit_get_addresses"),
        );
        return normalizeResponse(response);
      },
    },

    // ── 23. deposit_get_address ──────────────────────────────────
    {
      name: "deposit_get_address",
      module: "deposit",
      description:
        "개별 입금 주소를 조회합니다. Get deposit address for a specific currency and network. " +
        "For multi-network coins (USDT, USDC, XRP, etc.), run deposit_get_addresses first to confirm the correct net_type — wrong network = permanent loss of funds.",
      isWrite: false,
      inputSchema: {
        type: "object",
        properties: {
          currency: {
            type: "string",
            description: "Currency symbol, e.g. BTC",
          },
          net_type: {
            type: "string",
            description: "Network type, e.g. BTC, ETH",
          },
        },
        required: ["currency", "net_type"],
      },
      handler: async (rawArgs, context) => {
        const args = asRecord(rawArgs);
        const response = await context.client.privateGet(
          "/v1/deposits/coin_address",
          {
            currency: requireString(args, "currency"),
            net_type: requireString(args, "net_type"),
          },
          privateRateLimit("deposit_get_address"),
        );
        return normalizeResponse(response);
      },
    },
  ];
}
