import { readFileSync, writeFileSync, mkdirSync, existsSync, chmodSync } from "node:fs";
import { join, dirname } from "node:path";
import { homedir } from "node:os";
import { parse, stringify } from "smol-toml";
import { ConfigError } from "../utils/errors.js";

export { stringify as tomlStringify };

export interface BithumbProfile {
  access_key?: string;
  secret_key?: string;
  base_url?: string;
  timeout_ms?: number;
  read_only?: boolean;
}

export interface BithumbTomlConfig {
  default_profile?: string;
  profiles: Record<string, BithumbProfile>;
}

export function configFilePath(): string {
  return join(homedir(), ".bithumb", "config.toml");
}

export function readFullConfig(): BithumbTomlConfig {
  const path = configFilePath();
  if (!existsSync(path)) return { profiles: {} };
  const raw = readFileSync(path, "utf-8");
  try {
    return parse(raw) as unknown as BithumbTomlConfig;
  } catch (err) {
    throw new ConfigError(
      `Failed to parse ${path}: ${err instanceof Error ? err.message : String(err)}`,
      "Check TOML syntax in your config file, or delete and re-create it.",
    );
  }
}

// The single profile actually applied: an explicit name → else default_profile
// → else the literal "default". See CONTEXT.md "Effective profile".
export function resolveEffectiveProfileName(
  config: BithumbTomlConfig,
  profileName?: string,
): string {
  return profileName ?? config.default_profile ?? "default";
}

export function readTomlProfile(profileName?: string): BithumbProfile {
  const config = readFullConfig();
  const name = resolveEffectiveProfileName(config, profileName);
  return config.profiles?.[name] ?? {};
}

const CONFIG_HEADER =
  "# Bithumb Trade Kit Configuration\n" +
  "# Wrap values containing special chars in quotes\n\n";

// secret_key is stored in plaintext here (AWS-CLI-style convention), so the
// file must not be world/group readable. Set 0600 on the file and 0700 on the
// parent dir, and re-tighten an existing file on every rewrite.
export function writeFullConfig(config: BithumbTomlConfig, path = configFilePath()): void {
  const dir = dirname(path);
  if (!existsSync(dir)) {
    mkdirSync(dir, { recursive: true, mode: 0o700 });
  }
  writeFileSync(
    path,
    CONFIG_HEADER + stringify(config as unknown as Record<string, unknown>),
    { encoding: "utf-8", mode: 0o600 },
  );
  // writeFileSync's mode only applies when the file is created; chmod ensures a
  // pre-existing loosely-permissioned file is tightened too.
  chmodSync(path, 0o600);
}
