// ─── Tool Registry ─────────────────────────────────────────────────

import type { BithumbConfig } from "../config.js";
import type { BithumbRestClient } from "../client/rest-client.js";
import type { ToolSpec, ToolArgs } from "./types.js";
import { registerMarketTools } from "./market.js";
import { registerAccountTools } from "./account.js";
import { registerTradeTools } from "./trade.js";
import { registerAuditTools } from "./audit.js";
import { registerDiagnoseTools } from "./diagnose.js";
import { registerTwapTools } from "./twap.js";
import { registerWithdrawTools } from "./withdraw.js";
import { registerDepositTools } from "./deposit.js";

/** Return all registered tool specs. */
export function allToolSpecs(): ToolSpec[] {
  return [
    ...registerMarketTools(),
    ...registerAccountTools(),
    ...registerTradeTools(),
    ...registerAuditTools(),
    ...registerDiagnoseTools(),
    ...registerTwapTools(),
    ...registerWithdrawTools(),
    ...registerDepositTools(),
  ];
}

/** Filter tools by enabled modules and readOnly mode. */
export function buildTools(config: BithumbConfig): ToolSpec[] {
  const enabledModules = new Set(config.modules);
  const tools = allToolSpecs().filter((t) => enabledModules.has(t.module));
  if (!config.readOnly) return tools;
  return tools.map((t) =>
    t.isWrite
      ? {
          ...t,
          description:
            `⛔ DISABLED — read-only mode is active. This tool cannot be executed. To use this feature, restart without the --read-only flag. Original: ${t.description}`,
        }
      : t,
  );
}

export interface ToolResult {
  endpoint: string;
  requestTime: string;
  data: unknown;
}

export type ToolRunner = (
  toolName: string,
  args: ToolArgs,
) => Promise<ToolResult>;

/** Create a function that dispatches tool calls by name. */
export function createToolRunner(
  client: BithumbRestClient,
  config: BithumbConfig,
): ToolRunner {
  const tools = allToolSpecs();
  const toolMap = new Map<string, ToolSpec>(
    tools.map((t) => [t.name, t]),
  );

  return async (toolName, args) => {
    const tool = toolMap.get(toolName);
    if (!tool) throw new Error(`Unknown tool: ${toolName}`);
    if (config.readOnly && tool.isWrite) {
      throw new Error(`'${toolName}' is a write operation and cannot be used in read-only mode.`);
    }
    return (await tool.handler(args, { config, client })) as ToolResult;
  };
}
