// ─── Market Tools (Public) ─────────────────────────────────────────

import type { ToolSpec } from "./types.js";
import {
  asRecord,
  compactObject,
  normalizeResponse,
  readBoolean,
  readNumber,
  readString,
  requireString,
} from "./helpers.js";
import { publicRateLimit } from "./common.js";

export function registerMarketTools(): ToolSpec[] {
  return [
    // ── 1. market_get_markets ──────────────────────────────────────
    {
      name: "market_get_markets",
      module: "market",
      description:
        "빗썸 거래 가능한 마켓(거래 페어) 목록을 조회합니다. Get all available trading pairs on Bithumb. " +
        "Use when: user asks for the list of tradable markets. " +
        "isDetails: omit by default (API default: false). Pass isDetails=true ONLY when the user explicitly asks about 유의 종목 (Investment Caution Designation) status — this adds market_warning (NONE | CAUTION) per market. " +
        "Do NOT use: for 주의 종목/경보제 (Market Alert with level/reason/expiry) — use market_get_warnings instead. " +
        "Do NOT auto-call together with market_get_warnings unless the user explicitly asks for \"둘 다 / 전부\".",
      isWrite: false,
      inputSchema: {
        type: "object",
        properties: {
          isDetails: {
            type: "boolean",
            description:
              "true일 경우 응답 각 마켓에 market_warning 필드 포함 (유의 종목 / Investment Caution Designation 지정 상태, NONE | CAUTION). 단계/사유/해제 시각이 필요하면 market_get_warnings를 사용.",
          },
        },
        required: [],
      },
      handler: async (rawArgs, context) => {
        const args = asRecord(rawArgs);
        const response = await context.client.publicGet(
          "/v1/market/all",
          compactObject({ isDetails: readBoolean(args, "isDetails") }),
          publicRateLimit("market_get_markets"),
        );
        return normalizeResponse(response);
      },
    },

    // ── 2. market_get_ticker ───────────────────────────────────────
    {
      name: "market_get_ticker",
      module: "market",
      description:
        "현재가(Ticker) 정보를 조회합니다. Get current price ticker for specified markets.",
      isWrite: false,
      inputSchema: {
        type: "object",
        properties: {
          markets: {
            type: "string",
            description:
              "Comma-separated market codes, e.g. KRW-BTC,KRW-ETH",
          },
        },
        required: ["markets"],
      },
      handler: async (rawArgs, context) => {
        const args = asRecord(rawArgs);
        const response = await context.client.publicGet(
          "/v1/ticker",
          compactObject({ markets: requireString(args, "markets") }),
          publicRateLimit("market_get_ticker"),
        );
        return normalizeResponse(response);
      },
    },

    // ── 3. market_get_orderbook ────────────────────────────────────
    {
      name: "market_get_orderbook",
      module: "market",
      description:
        "호가(Orderbook) 정보를 조회합니다. Get orderbook (bids/asks) for specified markets.",
      isWrite: false,
      inputSchema: {
        type: "object",
        properties: {
          markets: {
            type: "string",
            description:
              "Comma-separated market codes, e.g. KRW-BTC,KRW-ETH",
          },
        },
        required: ["markets"],
      },
      handler: async (rawArgs, context) => {
        const args = asRecord(rawArgs);
        const response = await context.client.publicGet(
          "/v1/orderbook",
          compactObject({ markets: requireString(args, "markets") }),
          publicRateLimit("market_get_orderbook"),
        );
        return normalizeResponse(response);
      },
    },

    // ── 4. market_get_trades ───────────────────────────────────────
    {
      name: "market_get_trades",
      module: "market",
      description:
        "최근 체결 내역을 조회합니다. Get recent trades for a market.",
      isWrite: false,
      inputSchema: {
        type: "object",
        properties: {
          market: {
            type: "string",
            description: "Market code, e.g. KRW-BTC",
          },
          to: {
            type: "string",
            description:
              "조회 기준 시각 — time-of-day only (KST). 형식: HHmmss 또는 HH:mm:ss (00:00:00–23:59:59). 캔들 to와 달리 날짜는 받지 않는다 — 과거 일자는 daysAgo(1–7)로 지정. 미입력 시: daysAgo도 없으면 현재 시각 기준, daysAgo 있으면 해당 일자 00:00:00 기준.",
          },
          count: {
            type: "number",
            description: "Number of trades to return (1–500, default 1)",
          },
          cursor: {
            type: "string",
            description: "Pagination cursor — use sequential_id from previous response",
          },
          daysAgo: {
            type: "number",
            description:
              "Filter trades from N days ago (1–7). Without this, query targets the current time.",
          },
        },
        required: ["market"],
      },
      handler: async (rawArgs, context) => {
        const args = asRecord(rawArgs);
        const response = await context.client.publicGet(
          "/v1/trades/ticks",
          compactObject({
            market: requireString(args, "market"),
            to: readString(args, "to"),
            count: readNumber(args, "count"),
            cursor: readString(args, "cursor"),
            daysAgo: readNumber(args, "daysAgo"),
          }),
          publicRateLimit("market_get_trades"),
        );
        return normalizeResponse(response);
      },
    },

    // ── 5. market_get_candles_minutes ──────────────────────────────
    {
      name: "market_get_candles_minutes",
      module: "market",
      description:
        "분(minute) 캔들을 조회합니다. Get minute candles (OHLCV).",
      isWrite: false,
      inputSchema: {
        type: "object",
        properties: {
          unit: {
            type: "number",
            enum: [1, 3, 5, 10, 15, 30, 60, 240],
            description: "Candle unit in minutes",
          },
          market: {
            type: "string",
            description: "Market code, e.g. KRW-BTC",
          },
          to: {
            type: "string",
            description:
              "Fetch candles before this time (KST naive, no offset), exclusive (e.g. 2026-01-01T00:00:00)",
          },
          count: {
            type: "number",
            description: "Number of candles to return (max 200)",
          },
        },
        required: ["unit", "market"],
      },
      handler: async (rawArgs, context) => {
        const args = asRecord(rawArgs);
        const unit = readNumber(args, "unit");
        if (!unit) throw new Error('Missing required parameter "unit".');
        const response = await context.client.publicGet(
          `/v1/candles/minutes/${unit}`,
          compactObject({
            market: requireString(args, "market"),
            to: readString(args, "to"),
            count: readNumber(args, "count"),
          }),
          publicRateLimit("market_get_candles_minutes"),
        );
        return normalizeResponse(response);
      },
    },

    // ── 6. market_get_candles_days ─────────────────────────────────
    {
      name: "market_get_candles_days",
      module: "market",
      description:
        "일(day) 캔들을 조회합니다. Get daily candles.",
      isWrite: false,
      inputSchema: {
        type: "object",
        properties: {
          market: {
            type: "string",
            description: "Market code, e.g. KRW-BTC",
          },
          to: {
            type: "string",
            description:
              "Fetch candles before this time (KST naive, no offset), exclusive (e.g. 2026-01-01T00:00:00)",
          },
          count: {
            type: "number",
            description: "Number of candles to return (max 200)",
          },
          convertingPriceUnit: {
            type: "string",
            description:
              "Convert the close price (trade_price) to KRW for non-KRW markets such as BTC-ETH; the result populates the `converted_trade_price` field. " +
              "Bithumb supports KRW only. KRW-quoted markets (e.g. KRW-BTC) are already KRW and return null.",
          },
        },
        required: ["market"],
      },
      handler: async (rawArgs, context) => {
        const args = asRecord(rawArgs);
        const response = await context.client.publicGet(
          "/v1/candles/days",
          compactObject({
            market: requireString(args, "market"),
            to: readString(args, "to"),
            count: readNumber(args, "count"),
            convertingPriceUnit: readString(args, "convertingPriceUnit"),
          }),
          publicRateLimit("market_get_candles_days"),
        );
        return normalizeResponse(response);
      },
    },

    // ── 7. market_get_candles_weeks ────────────────────────────────
    {
      name: "market_get_candles_weeks",
      module: "market",
      description:
        "주(week) 캔들을 조회합니다. Get weekly candles.",
      isWrite: false,
      inputSchema: {
        type: "object",
        properties: {
          market: {
            type: "string",
            description: "Market code, e.g. KRW-BTC",
          },
          to: {
            type: "string",
            description:
              "Fetch candles before this time (KST naive, no offset), exclusive (e.g. 2026-01-01T00:00:00)",
          },
          count: {
            type: "number",
            description: "Number of candles to return (max 200)",
          },
        },
        required: ["market"],
      },
      handler: async (rawArgs, context) => {
        const args = asRecord(rawArgs);
        const response = await context.client.publicGet(
          "/v1/candles/weeks",
          compactObject({
            market: requireString(args, "market"),
            to: readString(args, "to"),
            count: readNumber(args, "count"),
          }),
          publicRateLimit("market_get_candles_weeks"),
        );
        return normalizeResponse(response);
      },
    },

    // ── 8. market_get_candles_months ───────────────────────────────
    {
      name: "market_get_candles_months",
      module: "market",
      description:
        "월(month) 캔들을 조회합니다. Get monthly candles.",
      isWrite: false,
      inputSchema: {
        type: "object",
        properties: {
          market: {
            type: "string",
            description: "Market code, e.g. KRW-BTC",
          },
          to: {
            type: "string",
            description:
              "Fetch candles before this time (KST naive, no offset), exclusive (e.g. 2026-01-01T00:00:00)",
          },
          count: {
            type: "number",
            description: "Number of candles to return (max 200)",
          },
        },
        required: ["market"],
      },
      handler: async (rawArgs, context) => {
        const args = asRecord(rawArgs);
        const response = await context.client.publicGet(
          "/v1/candles/months",
          compactObject({
            market: requireString(args, "market"),
            to: readString(args, "to"),
            count: readNumber(args, "count"),
          }),
          publicRateLimit("market_get_candles_months"),
        );
        return normalizeResponse(response);
      },
    },

    // ── 9. market_get_warnings ─────────────────────────────────────
    {
      name: "market_get_warnings",
      module: "market",
      description:
        "주의 종목/경보제(Market Alert) 목록을 조회합니다. Get the market alert list — markets currently flagged by Bithumb's automated detection. " +
        "Use when: user asks about 주의 종목 / 경보 / 이상거래 탐지, or wants warning_step (CAUTION/WARNING/DANGER) / warning_type (5 reasons) / end_date (auto-clear time). " +
        "Do NOT use: for 유의 종목 (Investment Caution Designation, exchange-curated NONE/CAUTION) — use market_get_markets with isDetails=true instead. " +
        "Do NOT auto-call together with market_get_markets unless the user explicitly asks for \"둘 다 / 전부\".",
      isWrite: false,
      inputSchema: {
        type: "object",
        properties: {},
        required: [],
      },
      handler: async (_rawArgs, context) => {
        const response = await context.client.publicGet(
          "/v1/market/virtual_asset_warning",
          {},
          publicRateLimit("market_get_warnings"),
        );
        return normalizeResponse(response);
      },
    },

    // ── 10. market_get_notices ─────────────────────────────────────
    {
      name: "market_get_notices",
      module: "market",
      description:
        "공지사항 목록을 조회합니다. Get notice list.",
      isWrite: false,
      inputSchema: {
        type: "object",
        properties: {
          count: {
            type: "number",
            description: "Number of notices to return (min 1, max 20, default 5)",
          },
        },
        required: [],
      },
      handler: async (rawArgs, context) => {
        const args = asRecord(rawArgs);
        const count = readNumber(args, "count");
        const response = await context.client.publicGet(
          "/v1/notices",
          compactObject({ count }),
          publicRateLimit("market_get_notices"),
        );
        return normalizeResponse(response);
      },
    },

    // ── 11. market_get_fee_inout ───────────────────────────────────
    {
      name: "market_get_fee_inout",
      module: "market",
      description:
        "입출금 수수료를 조회합니다. Get deposit/withdrawal fee info for a currency.",
      isWrite: false,
      inputSchema: {
        type: "object",
        properties: {
          currency: {
            type: "string",
            description:
              'Currency symbol (use "ALL" to retrieve all currencies), e.g. BTC, ETH',
          },
        },
        required: ["currency"],
      },
      handler: async (rawArgs, context) => {
        const args = asRecord(rawArgs);
        const currency = requireString(args, "currency");
        const response = await context.client.publicGet(
          `/v2/fee/inout/${currency}`,
          {},
          publicRateLimit("market_get_fee_inout"),
        );
        return normalizeResponse(response);
      },
    },
  ];
}
