// ─── TWAP Tools (Private) ─────────────────────────────────────────

import type { ToolSpec } from "./types.js";
import {
  asRecord,
  compactObject,
  normalizeResponse,
  readNumber,
  readString,
  readStringArray,
  requireString,
} from "./helpers.js";
import { orderRateLimit, privateRateLimit } from "./common.js";

export function registerTwapTools(): ToolSpec[] {
  return [
    // ── 6. twap_place_order ────────────────────────────────────────
    {
      name: "twap_place_order",
      module: "twap",
      description:
        "TWAP 주문을 요청합니다. Place a TWAP (Time-Weighted Average Price) order. " +
        "⚠️ REQUIRES EXPLICIT USER CONFIRMATION before executing: show the user market, side, price/volume, duration, frequency, and computed slice count (duration ÷ frequency), then wait for explicit approval. Do NOT place the order without user confirmation. " +
        "CLI-first: when the Bithumb CLI is installed, prefer the documented `bithumb ...` CLI command for this write operation; use this MCP tool as fallback when the CLI is unavailable/fails or the user explicitly asks for MCP.",
      isWrite: true,
      inputSchema: {
        type: "object",
        properties: {
          market: {
            type: "string",
            description: "거래 대상 페어의 고유 심볼 (예시: KRW-BTC)",
          },
          side: {
            type: "string",
            enum: ["bid", "ask"],
            description: "주문 종류: bid (매수), ask (매도)",
          },
          duration: {
            type: "string",
            description:
              "주문 시간 - TWAP 주문이 진행되는 시간(초). min 300, max 43200",
          },
          frequency: {
            type: "string",
            enum: ["15", "20", "30", "60", "120"],
            description: "주문 간격(초)",
          },
          volume: {
            type: "string",
            description: "주문 수량 (매도 시 필수)",
          },
          price: {
            type: "string",
            description: "주문 가격 (매수 시 필수)",
          },
        },
        required: ["market", "side", "duration", "frequency"],
      },
      handler: async (rawArgs, context) => {
        const args = asRecord(rawArgs);
        const response = await context.client.privatePost(
          "/v1/twap",
          compactObject({
            market: requireString(args, "market"),
            side: requireString(args, "side"),
            duration: requireString(args, "duration"),
            frequency: requireString(args, "frequency"),
            volume: readString(args, "volume"),
            price: readString(args, "price"),
          }),
          orderRateLimit("twap_place_order"),
        );
        return normalizeResponse(response);
      },
    },

    // ── 7. twap_get_orders ─────────────────────────────────────────
    {
      name: "twap_get_orders",
      module: "twap",
      description:
        "TWAP 주문 내역을 조회합니다. Get TWAP order history. " +
        "Use after twap_place_order to verify the order is active (state: progress). " +
        "Default state filter is 'progress'; pass state: 'done' or 'cancel' to query completed or cancelled orders.",
      isWrite: false,
      inputSchema: {
        type: "object",
        properties: {
          market: {
            type: "string",
            description: "거래 대상 페어의 고유 심볼 (예시: KRW-BTC)",
          },
          order_ids: {
            type: "array",
            items: { type: "string" },
            description: "TWAP 주문 ID 목록",
          },
          state: {
            type: "string",
            enum: ["progress", "done", "cancel"],
            description:
              "주문 상태: progress (진행중, default), done (완료), cancel (취소)",
          },
          next_key: {
            type: "string",
            description: "다음 페이지 조회를 위한 커서 값",
          },
          limit: {
            type: "number",
            description: "개수 제한 (max 100)",
          },
          order_by: {
            type: "string",
            enum: ["asc", "desc"],
            description: "조회 결과 정렬 방식: asc (오름차순), desc (내림차순, default)",
          },
        },
        required: [],
      },
      handler: async (rawArgs, context) => {
        const args = asRecord(rawArgs);
        // Exposed param is `order_ids`, but the Bithumb GET /v1/twap endpoint
        // expects it in the `uuids` field (legacy naming — the "uuids" are
        // actually order_ids; same value the cancel endpoint calls algo_order_id).
        const response = await context.client.privateGet(
          "/v1/twap",
          compactObject({
            market: readString(args, "market"),
            uuids: readStringArray(args, "order_ids"),
            state: readString(args, "state"),
            next_key: readString(args, "next_key"),
            limit: readNumber(args, "limit"),
            order_by: readString(args, "order_by"),
          }),
          privateRateLimit("twap_get_orders"),
        );
        return normalizeResponse(response);
      },
    },

    // ── 8. twap_cancel_order ───────────────────────────────────────
    {
      name: "twap_cancel_order",
      module: "twap",
      description:
        "TWAP 주문을 취소합니다. Cancel a TWAP order. " +
        "⚠️ REQUIRES EXPLICIT USER CONFIRMATION before executing: show the user the TWAP order ID and wait for explicit approval. Do NOT cancel without user confirmation. " +
        "CLI-first: when the Bithumb CLI is installed, prefer the documented `bithumb ...` CLI command for this write operation; use this MCP tool as fallback when the CLI is unavailable/fails or the user explicitly asks for MCP.",
      isWrite: true,
      inputSchema: {
        type: "object",
        properties: {
          algo_order_id: {
            type: "string",
            description: "취소할 TWAP 주문 ID",
          },
        },
        required: ["algo_order_id"],
      },
      handler: async (rawArgs, context) => {
        const args = asRecord(rawArgs);
        const algo_order_id = requireString(args, "algo_order_id");
        const response = await context.client.privateDelete(
          "/v1/twap",
          { algo_order_id },
          orderRateLimit("twap_cancel_order"),
        );
        return normalizeResponse(response);
      },
    },
  ];
}
