import { ConfigError } from "../utils/errors.js";

// ITQA-55656 / ADR 0013: shared config-value validation, used at the CLI write
// surface and the core read surface so both enforce the identical rule.

const TIMEOUT_MIN = 1;
const TIMEOUT_MAX = 60_000;

// A timeout_ms is valid iff a finite integer in [1, 60000]. 60000 ms (60 s) is
// above the 30000 ms default while still allowing explicit slower-call tuning, so a
// larger value is a typo, not a tuning choice.
export function validateTimeoutMs(value: number): number {
  if (!Number.isInteger(value) || value < TIMEOUT_MIN || value > TIMEOUT_MAX) {
    throw new ConfigError(
      "Invalid timeout.",
      `timeout_ms must be an integer between ${TIMEOUT_MIN} and ${TIMEOUT_MAX} (milliseconds).`,
    );
  }
  return value;
}

const PROFILE_NAME_RE = /^[A-Za-z0-9._-]+$/;

// A profile name is valid iff it matches [A-Za-z0-9._-]+. This is exactly what
// survives as a single shell token in `config use <name>` / `--profile <name>`
// (a name with spaces is created but then unreachable) and what embeds cleanly
// as a TOML table key without quoting. Unicode/spaced names are rejected by
// design, not oversight.
export function validateProfileName(name: string): string {
  if (!PROFILE_NAME_RE.test(name)) {
    throw new ConfigError(
      `Invalid profile name: ${JSON.stringify(name)}.`,
      "A profile name may contain only letters, digits, '.', '_', and '-' (no spaces).",
    );
  }
  return name;
}
