import { Server } from "@modelcontextprotocol/sdk/server/index.js";
import {
  CallToolRequestSchema,
  ListToolsRequestSchema,
  type CallToolResult,
} from "@modelcontextprotocol/sdk/types.js";
import {
  BithumbRestClient,
  buildTools,
  BithumbApiError,
  toToolErrorPayload,
  toMcpTool,
} from "@bithumb-official/bithumb-core";
import type { BithumbConfig, ToolSpec, TradeLogger } from "@bithumb-official/bithumb-core";
import { SERVER_NAME, SERVER_VERSION } from "./constants.js";

function successResult(toolName: string, data: unknown): CallToolResult {
  const payload: Record<string, unknown> = {
    tool: toolName, ok: true, data, timestamp: new Date().toISOString(),
  };
  return {
    content: [{ type: "text", text: JSON.stringify(payload, null, 2) }],
    structuredContent: payload,
  };
}

function errorResult(toolName: string, error: unknown): CallToolResult {
  const payload = toToolErrorPayload(error);
  const structured: Record<string, unknown> = {
    tool: toolName, ...payload, serverVersion: SERVER_VERSION,
  };
  return {
    isError: true,
    content: [{ type: "text", text: JSON.stringify(structured, null, 2) }],
    structuredContent: structured,
  };
}

function unknownToolResult(toolName: string): CallToolResult {
  return errorResult(
    toolName,
    new BithumbApiError(`Tool "${toolName}" is not available.`, { code: "TOOL_NOT_AVAILABLE" }),
  );
}

export function createServer(config: BithumbConfig, logger?: TradeLogger): Server {
  const client = new BithumbRestClient(config);
  const tools = buildTools(config);
  const toolMap = new Map<string, ToolSpec>(tools.map((t) => [t.name, t]));

  const server = new Server(
    { name: SERVER_NAME, version: SERVER_VERSION },
    { capabilities: { tools: {} } },
  );

  server.setRequestHandler(ListToolsRequestSchema, async () => {
    return { tools: tools.map(toMcpTool) };
  });

  server.setRequestHandler(CallToolRequestSchema, async (request) => {
    const toolName = request.params.name;

    const tool = toolMap.get(toolName);
    if (!tool) return unknownToolResult(toolName);

    // read-only 모드에서 write 도구 실행 차단 (CLI createToolRunner와 동일 정책).
    // buildTools는 description에 DISABLED 라벨만 붙이므로, 실제 차단은 여기서 강제한다.
    if (config.readOnly && tool.isWrite) {
      return errorResult(
        toolName,
        new BithumbApiError(
          `'${toolName}' is a write operation and cannot be used in read-only mode.`,
          { code: "READ_ONLY_MODE" },
        ),
      );
    }

    const startTime = Date.now();
    try {
      const response = await tool.handler(request.params.arguments ?? {}, { config, client });
      logger?.logTool("info", toolName, request.params.arguments ?? {}, response, Date.now() - startTime);
      return successResult(toolName, response);
    } catch (error) {
      const level = error instanceof BithumbApiError ? "warn" : "error";
      logger?.logTool(level, toolName, request.params.arguments ?? {}, error, Date.now() - startTime);
      return errorResult(toolName, error);
    }
  });

  return server;
}
