// ─── Bithumb REST Client ───────────────────────────────────────────

import { signRequest } from "../utils/signature.js";
import {
  AuthenticationError,
  BithumbApiError,
  ConfigError,
  NetworkError,
  RateLimitError,
} from "../utils/errors.js";
import { RateLimiter } from "../utils/rate-limiter.js";
import { TRADE_KIT_HEADER } from "../constants.js";
import type { BithumbConfig } from "../config.js";
import type {
  BithumbErrorResponse,
  QueryParams,
  RequestConfig,
  RequestResult,
} from "./types.js";

// ─── Helpers ───────────────────────────────────────────────────────

function isDefined(value: unknown): boolean {
  return value !== undefined && value !== null;
}

/**
 * Build the URL-encoded query string for GET params (ITQA-55503).
 *
 * Encoding is RFC3986-strict via encodeURIComponent — every reserved/special
 * character (space → %20, ':' → %3A, ',' → %2C, …) is percent-encoded. This
 * matches the canonical Upbit SDK serialization (qs with default RFC3986), so
 * the CLI emits the same bytes a standards-compliant client would.
 *
 * Known server limitation (NOT a client bug): Bithumb's list endpoints
 * (/v1/withdraws, /v1/deposits) fail to match txid values that contain a space
 * or comma even when correctly percent-encoded — the single-record endpoints
 * (/v1/withdraw, /v1/deposit) match them fine. So a txid like
 * "2025-08-04 20:33:13.452665" or "EVENT_COUPON:4,649" must be looked up via the
 * single-record get (txid) rather than the list txids filter. The CLI/MCP and
 * skill docs route the user to the single-record path for such values.
 */
export function buildQueryString(query?: QueryParams): string {
  if (!query) return "";
  const entries = Object.entries(query).filter(([, v]) => isDefined(v));
  if (entries.length === 0) return "";

  const parts: string[] = [];
  for (const [key, value] of entries) {
    if (Array.isArray(value)) {
      for (let i = 0; i < value.length; i++) {
        const item = value[i];
        if (item && typeof item === "object" && !Array.isArray(item)) {
          for (const [subKey, subVal] of Object.entries(item as Record<string, unknown>)) {
            parts.push(
              `${encodeURIComponent(key)}[${i}][${encodeURIComponent(subKey)}]=${encodeURIComponent(String(subVal))}`,
            );
          }
        } else {
          parts.push(
            `${encodeURIComponent(key)}[]=${encodeURIComponent(String(item))}`,
          );
        }
      }
    } else {
      parts.push(
        `${encodeURIComponent(key)}=${encodeURIComponent(String(value))}`,
      );
    }
  }
  return parts.join("&");
}

/** Build unencoded query string for JWT hash computation. */
export function buildHashString(
  query?: QueryParams,
  body?: Record<string, unknown>,
): string {
  const source = body ?? query;
  if (!source) return "";
  const entries = Object.entries(source).filter(([, v]) => isDefined(v));
  if (entries.length === 0) return "";

  const parts: string[] = [];
  for (const [key, value] of entries) {
    if (Array.isArray(value)) {
      for (let i = 0; i < value.length; i++) {
        const item = value[i];
        if (item && typeof item === "object" && !Array.isArray(item)) {
          for (const [subKey, subVal] of Object.entries(item as Record<string, unknown>)) {
            parts.push(`${key}[${i}][${subKey}]=${String(subVal)}`);
          }
        } else {
          parts.push(`${key}[]=${String(item)}`);
        }
      }
    } else {
      parts.push(`${key}=${String(value)}`);
    }
  }
  return parts.join("&");
}

function vlog(message: string): void {
  process.stderr.write(`[verbose] ${message}\n`);
}

// ─── Client ────────────────────────────────────────────────────────

export class BithumbRestClient {
  private readonly config: BithumbConfig;
  private readonly rateLimiter: RateLimiter;

  constructor(config: BithumbConfig) {
    this.config = config;
    this.rateLimiter = new RateLimiter(30_000, config.verbose);
  }

  async publicGet<TData = unknown>(
    path: string,
    query?: QueryParams,
    rateLimit?: RequestConfig["rateLimit"],
  ): Promise<RequestResult<TData>> {
    return this.request<TData>({
      method: "GET",
      path,
      auth: "public",
      query,
      rateLimit,
    });
  }

  async privateGet<TData = unknown>(
    path: string,
    query?: QueryParams,
    rateLimit?: RequestConfig["rateLimit"],
  ): Promise<RequestResult<TData>> {
    return this.request<TData>({
      method: "GET",
      path,
      auth: "private",
      query,
      rateLimit,
    });
  }

  async privatePost<TData = unknown>(
    path: string,
    body?: RequestConfig["body"],
    rateLimit?: RequestConfig["rateLimit"],
  ): Promise<RequestResult<TData>> {
    return this.request<TData>({
      method: "POST",
      path,
      auth: "private",
      body,
      rateLimit,
    });
  }

  async privateDelete<TData = unknown>(
    path: string,
    query?: QueryParams,
    rateLimit?: RequestConfig["rateLimit"],
  ): Promise<RequestResult<TData>> {
    return this.request<TData>({
      method: "DELETE",
      path,
      auth: "private",
      query,
      rateLimit,
    });
  }

  // ─── Core request ────────────────────────────────────────────────

  private async request<TData = unknown>(
    reqConfig: RequestConfig,
  ): Promise<RequestResult<TData>> {
    const queryString = buildQueryString(reqConfig.query);
    const requestPath =
      queryString.length > 0
        ? `${reqConfig.path}?${queryString}`
        : reqConfig.path;
    const url = `${this.config.baseUrl}${requestPath}`;

    if (this.config.verbose) vlog(`→ ${reqConfig.method} ${url}`);

    // Rate limiting
    if (reqConfig.rateLimit) await this.rateLimiter.consume(reqConfig.rateLimit);

    // Headers
    const headers: Record<string, string> = {
      "Content-Type": "application/json",
      Accept: "application/json",
      [TRADE_KIT_HEADER]: this.config.clientType,
    };

    // Auth: JWT Bearer token
    if (reqConfig.auth === "private") {
      if (
        !this.config.hasAuth ||
        !this.config.accessKey ||
        !this.config.secretKey
      ) {
        throw new ConfigError(
          "Private endpoint requires API credentials.",
          "Set BITHUMB_ACCESS_KEY and BITHUMB_SECRET_KEY.",
        );
      }
      const hashStr = buildHashString(reqConfig.query, reqConfig.body);
      const token = signRequest(
        this.config.accessKey,
        this.config.secretKey,
        hashStr,
      );
      headers["Authorization"] = `Bearer ${token}`;
    }

    // Fetch
    const t0 = Date.now();
    let response: Response;
    try {
      const fetchOptions: RequestInit = {
        method: reqConfig.method,
        headers,
        signal: AbortSignal.timeout(this.config.timeoutMs),
      };
      if (reqConfig.body && reqConfig.method === "POST") {
        fetchOptions.body = JSON.stringify(reqConfig.body);
      }
      response = await fetch(url, fetchOptions);
    } catch (error) {
      if (this.config.verbose) {
        vlog(`✗ NetworkError after ${Date.now() - t0}ms`);
      }
      throw new NetworkError(
        `Failed to call ${reqConfig.method} ${reqConfig.path}.`,
        `${reqConfig.method} ${reqConfig.path}`,
        error,
      );
    }

    // Parse response
    const rawText = await response.text();
    const elapsed = Date.now() - t0;
    if (this.config.verbose) {
      vlog(`← ${response.status} | ${rawText.length}B | ${elapsed}ms`);
    }

    let parsed: unknown;
    try {
      parsed = rawText ? JSON.parse(rawText) : null;
    } catch {
      throw new NetworkError(
        `Non-JSON response from ${reqConfig.method} ${reqConfig.path}.`,
        `${reqConfig.method} ${reqConfig.path}`,
      );
    }

    // Error handling: Bithumb returns { error: { name, message } }
    // - error.name 은 HTTP 코드가 아닌 자유 문자열(invalid_jwt, too_many_requests 등)이라
    //   분기 키로 신뢰할 수 없다. 분기는 HTTP response.status 로만 한다.
    // - 사용자에게는 name + message 를 그대로 결합해 노출. 한쪽이 없으면 있는 쪽만,
    //   둘 다 없으면 최후 fallback 으로 HTTP <status> 사용.
    if (parsed && typeof parsed === "object" && "error" in parsed) {
      const errResp = parsed as BithumbErrorResponse;
      const errName = errResp.error?.name;
      const errMsg = errResp.error?.message;
      const displayMsg =
        [errName, errMsg].filter(Boolean).join(": ") ||
        `HTTP ${response.status}`;
      const endpoint = `${reqConfig.method} ${reqConfig.path}`;

      if (response.status === 401) {
        throw new AuthenticationError(
          displayMsg,
          "Check BITHUMB_ACCESS_KEY and BITHUMB_SECRET_KEY.",
          endpoint,
        );
      }
      if (response.status === 429) {
        throw new RateLimitError(
          displayMsg,
          "Reduce request frequency.",
          endpoint,
        );
      }
      throw new BithumbApiError(displayMsg, {
        code: errName ?? String(response.status),
        endpoint,
      });
    }

    if (!response.ok) {
      throw new BithumbApiError(`HTTP ${response.status}`, {
        code: String(response.status),
        endpoint: `${reqConfig.method} ${reqConfig.path}`,
      });
    }

    return {
      endpoint: `${reqConfig.method} ${reqConfig.path}`,
      requestTime: new Date().toISOString(),
      data: parsed as TData,
    };
  }
}
