import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";

const CACHE_DIR = join(homedir(), ".bithumb");
const CACHE_FILE = join(CACHE_DIR, "update-check.json");
const CACHE_TTL_MS = 24 * 60 * 60 * 1000; // 24 hours

interface UpdateCache {
  latestVersion: string;
  checkedAt: number;
}

export function isNewerVersion(current: string, latest: string): boolean {
  const parse = (v: string): number[] =>
    v
      .replace(/^v/, "")
      .split(".")
      .map((n) => parseInt(n, 10) || 0);

  const cur = parse(current);
  const lat = parse(latest);

  for (let i = 0; i < Math.max(cur.length, lat.length); i++) {
    const c = cur[i] ?? 0;
    const l = lat[i] ?? 0;
    if (l > c) return true;
    if (l < c) return false;
  }
  return false;
}

export async function fetchDistTags(
  packageName: string
): Promise<Record<string, string> | null> {
  try {
    const url = `https://registry.npmjs.org/-/package/${encodeURIComponent(packageName)}/dist-tags`;
    const res = await fetch(url, { signal: AbortSignal.timeout(5000) });
    if (!res.ok) return null;
    return (await res.json()) as Record<string, string>;
  } catch {
    return null;
  }
}

export async function fetchLatestVersion(
  packageName: string
): Promise<string | null> {
  const tags = await fetchDistTags(packageName);
  return tags?.latest ?? null;
}

function readCache(): UpdateCache | null {
  try {
    if (!existsSync(CACHE_FILE)) return null;
    const raw = readFileSync(CACHE_FILE, "utf8");
    return JSON.parse(raw) as UpdateCache;
  } catch {
    return null;
  }
}

function writeCache(data: UpdateCache): void {
  try {
    if (!existsSync(CACHE_DIR)) {
      mkdirSync(CACHE_DIR, { recursive: true });
    }
    writeFileSync(CACHE_FILE, JSON.stringify(data), "utf8");
  } catch {
    // ignore write errors
  }
}

function isCacheStale(cache: UpdateCache): boolean {
  return Date.now() - cache.checkedAt > CACHE_TTL_MS;
}

export function checkForUpdates(
  packageName: string,
  currentVersion: string
): void {
  try {
    const cache = readCache();

    if (cache && !isCacheStale(cache)) {
      if (isNewerVersion(currentVersion, cache.latestVersion)) {
        process.stderr.write(
          `\nUpdate available: ${currentVersion} → ${cache.latestVersion}\n` +
            `Run: npm install -g ${packageName}\n\n`
        );
      }
      return;
    }

    // Cache is stale or missing — refresh in background
    // Use setImmediate so it doesn't block the current tick
    setImmediate(() => {
      fetchLatestVersion(packageName)
        .then((latest) => {
          if (latest) {
            writeCache({ latestVersion: latest, checkedAt: Date.now() });
            if (isNewerVersion(currentVersion, latest)) {
              process.stderr.write(
                `\nUpdate available: ${currentVersion} → ${latest}\n` +
                  `Run: npm install -g ${packageName}\n\n`
              );
            }
          }
        })
        .catch(() => {
          // ignore network errors
        });
    });
  } catch {
    // update check must never crash the main process
  }
}
