// ─── Audit / Log History Tools ─────────────────────────────────────

import fs from "node:fs";
import path from "node:path";
import os from "node:os";
import type { ToolSpec } from "./types.js";
import { asRecord, readNumber, readString } from "./helpers.js";
import type { LogEntry } from "../utils/logger.js";

const DEFAULT_LOG_DIR = path.join(os.homedir(), ".bithumb", "logs");

/** Generate file paths for the last N days (default 7). */
function getLogPaths(logDir: string, days = 7): string[] {
  const paths: string[] = [];
  const now = new Date();
  for (let i = 0; i < days; i++) {
    const d = new Date(now);
    d.setDate(d.getDate() - i);
    const yyyy = d.getFullYear();
    const mm = String(d.getMonth() + 1).padStart(2, "0");
    const dd = String(d.getDate()).padStart(2, "0");
    paths.push(path.join(logDir, `trade-${yyyy}-${mm}-${dd}.log`));
  }
  return paths;
}

/** Read and parse all log entries from files in the log directory. */
function readEntries(logDir: string): LogEntry[] {
  const filePaths = getLogPaths(logDir);
  const entries: LogEntry[] = [];

  for (const filePath of filePaths) {
    if (!fs.existsSync(filePath)) continue;
    let content: string;
    try {
      content = fs.readFileSync(filePath, "utf8");
    } catch {
      continue;
    }
    for (const line of content.split("\n")) {
      const trimmed = line.trim();
      if (!trimmed) continue;
      try {
        const entry = JSON.parse(trimmed) as LogEntry;
        entries.push(entry);
      } catch {
        // skip malformed lines
      }
    }
  }

  return entries;
}

/** Extract tool name from a LogEntry. */
function extractTool(entry: LogEntry): string | undefined {
  if (entry.tool) return entry.tool;
  if (typeof entry.message === "string" && entry.message.startsWith("tool:")) {
    return entry.message.slice("tool:".length);
  }
  return undefined;
}

export function registerAuditTools(logDir?: string): ToolSpec[] {
  const resolvedLogDir = logDir ?? DEFAULT_LOG_DIR;
  return [
    // ── system_get_audit_log ───────────────────────────────────────
    {
      name: "system_get_audit_log",
      module: "system",
      description:
        "로컬 로그에서 거래 이력을 조회합니다. Read local audit logs filtered by tool, level, and time.",
      isWrite: false,
      inputSchema: {
        type: "object",
        properties: {
          limit: {
            type: "number",
            description: "Maximum number of entries to return (default 20).",
          },
          tool: {
            type: "string",
            description: "Filter by tool name.",
          },
          level: {
            type: "string",
            enum: ["INFO", "WARN", "ERROR", "DEBUG"],
            description: "Filter by log level (case-insensitive).",
          },
          since: {
            type: "string",
            description: "ISO 8601 timestamp; return entries at or after this time.",
          },
        },
        required: [],
      },
      handler: async (rawArgs, _context) => {
        const args = asRecord(rawArgs);
        const limit = readNumber(args, "limit") ?? 20;
        const toolFilter = readString(args, "tool");
        const levelFilter = readString(args, "level")?.toLowerCase();
        const sinceStr = readString(args, "since");
        const sinceMs = sinceStr ? new Date(sinceStr).getTime() : undefined;

        const entries = readEntries(resolvedLogDir);

        const filtered = entries.filter((entry) => {
          if (toolFilter) {
            const t = extractTool(entry);
            if (!t || !t.includes(toolFilter)) return false;
          }
          if (levelFilter && entry.level !== levelFilter) return false;
          if (sinceMs !== undefined) {
            const entryMs = new Date(entry.ts).getTime();
            if (Number.isNaN(entryMs) || entryMs < sinceMs) return false;
          }
          return true;
        });

        // Sort descending by ts
        filtered.sort((a, b) => {
          const ta = new Date(a.ts).getTime();
          const tb = new Date(b.ts).getTime();
          return tb - ta;
        });

        return {
          endpoint: "local:audit-log",
          requestTime: new Date().toISOString(),
          data: filtered.slice(0, limit),
        };
      },
    },
  ];
}
