// ─── Trade Tools (Private) ─────────────────────────────────────────

import type { ToolSpec } from "./types.js";
import {
  asRecord,
  compactObject,
  normalizeResponse,
  readNumber,
  readString,
  readStringArray,
  requireString,
} from "./helpers.js";
import { orderRateLimit, privateRateLimit } from "./common.js";
import { ValidationError } from "../utils/errors.js";

export function registerTradeTools(): ToolSpec[] {
  return [
    // ── 1. trade_get_order ─────────────────────────────────────────
    {
      name: "trade_get_order",
      module: "trade",
      description:
        "개별(단건) 주문을 조회합니다. Get a SINGLE order by order_id or client_order_id. " +
        "Use when: you have exactly one order identifier. " +
        "Do NOT use: for multiple orders at once — do NOT call this repeatedly. " +
        "Pass all identifiers to trade_get_orders (order_ids/client_order_ids arrays) in a single call instead. " +
        "ID 라우팅: 사용자가 명시적으로 'client-order-id'라고 표현했으면 즉시 client_order_id로 조회. " +
        "그 외에는 order_id로 먼저 조회 → 결과가 없으면(order_not_found / 404) client_order_id로 다시 조회(폴백)한다. " +
        "Bithumb은 client_order_id 형식을 강제하지 않아 사용자가 order_id 패턴(C+숫자)과 동일하게 만들 수 있으므로 입력값으로 추측하지 않는다. " +
        'Example call: {"order_id":"C0101..."}',
      isWrite: false,
      inputSchema: {
        type: "object",
        properties: {
          order_id: {
            type: "string",
            description: "Order ID",
          },
          client_order_id: {
            type: "string",
            description: "Client-assigned order ID (1–36 chars; letters, digits, hyphens, underscores only)",
          },
        },
        required: [],
      },
      handler: async (rawArgs, context) => {
        const args = asRecord(rawArgs);
        // Exposed param is `order_id`, but the Bithumb v1 endpoint expects it in
        // the `uuid` field (legacy naming — the v1 "uuid" is actually the order_id).
        const response = await context.client.privateGet(
          "/v1/order",
          compactObject({
            uuid: readString(args, "order_id"),
            client_order_id: readString(args, "client_order_id"),
          }),
          privateRateLimit("trade_get_order"),
        );
        return normalizeResponse(response);
      },
    },

    // ── 2. trade_get_orders ────────────────────────────────────────
    {
      name: "trade_get_orders",
      module: "trade",
      description:
        "주문 리스트/복수 주문을 조회합니다. Get orders — fetch MULTIPLE specific orders in one call via order_ids/client_order_ids (arrays), or list by market/state filters. " +
        "Use when: the user gives two or more order numbers, or wants a filtered list. " +
        "Do NOT use trade_get_order repeatedly for multiple ids — pass them all here in one call. " +
        "Note: the server defaults to state=wait when omitted, so to fetch done/cancel orders (e.g. by order_ids) set states explicitly, e.g. states=[\"wait\",\"done\",\"cancel\"]. " +
        "The auto-order state (watch) CANNOT be mixed with general states (wait/done/cancel); query it separately with state=watch. state and states cannot be used together. " +
        "Batch size: up to 100 ids per call (server limit). For more than 100, split into chunks of 100. " +
        'Example call: {"order_ids":["C0101...","C0102..."],"states":["wait","done","cancel"]}',
      isWrite: false,
      inputSchema: {
        type: "object",
        properties: {
          market: {
            type: "string",
            description: "Market code, e.g. KRW-BTC",
          },
          state: {
            type: "string",
            enum: ["wait", "watch", "done", "cancel"],
            description: "Order state filter",
          },
          states: {
            type: "array",
            items: { type: "string" },
            description:
              "Multiple order state filters. Constraints: general states (wait/done/cancel) and the auto-order state (watch) CANNOT be mixed in one query; state and states cannot be used together. If omitted, the server defaults to state=wait — pass states=[\"wait\",\"done\",\"cancel\"] to include done/cancel orders.",
          },
          order_ids: {
            type: "array",
            items: { type: "string" },
            description: "Fetch multiple specific orders by order ID in one call (batch lookup). Pass all order IDs here instead of calling trade_get_order repeatedly. Up to 100 ids per call (max 100).",
          },
          client_order_ids: {
            type: "array",
            items: { type: "string" },
            description: "Fetch multiple orders by client-assigned order ID in one call (batch lookup, max 100). Each id: 1–36 chars; letters, digits, hyphens, underscores only. Pass all client order IDs here instead of calling trade_get_order repeatedly.",
          },
          page: {
            type: "number",
            description: "Page number",
          },
          limit: {
            type: "number",
            description: "Number of results per page",
          },
          order_by: {
            type: "string",
            enum: ["asc", "desc"],
            description: "Sort order: asc (oldest first) or desc (newest first, default)",
          },
        },
        required: [],
      },
      handler: async (rawArgs, context) => {
        const args = asRecord(rawArgs);
        // Exposed param is `order_ids`, but the Bithumb v1 endpoint expects it in
        // the `uuids` field (legacy naming — the v1 "uuids" are actually order_ids).
        const response = await context.client.privateGet(
          "/v1/orders",
          compactObject({
            market: readString(args, "market"),
            state: readString(args, "state"),
            states: readStringArray(args, "states"),
            uuids: readStringArray(args, "order_ids"),
            client_order_ids: readStringArray(args, "client_order_ids"),
            page: readNumber(args, "page"),
            limit: readNumber(args, "limit"),
            order_by: readString(args, "order_by"),
          }),
          privateRateLimit("trade_get_orders"),
        );
        return normalizeResponse(response);
      },
    },

    // ── 3. trade_place_order ───────────────────────────────────────
    {
      name: "trade_place_order",
      module: "trade",
      description:
        "주문을 생성합니다. Place a new spot order on Bithumb. " +
        "Use when: user asks to buy/sell a single market at a specific price or quantity. " +
        "Do NOT use: for multiple orders at once (use trade_batch_place); for time-weighted execution (use twap_place). " +
        "Field: order_type ∈ {limit, price, market}. limit: price+volume required. price(시장가 매수): only price (total KRW). market(시장가 매도): only volume (coin qty). " +
        "모든 limit 가격은 출처(직접 입력·계산·퍼센트)와 무관하게 호가단위(price tick)에 정렬돼야 한다. 정렬되지 않은 가격(예: 123,456원)은 빗썸이 거부하므로 가장 가까운 유효 호가로 round 정규화한 뒤, 확인 단계에서 원본/보정값을 함께 보여준다 (표·절차는 bithumb-trade 스킬 order-commands.md). " +
        "Note: Bithumb API response field is `ord_type` (not `order_type`). " +
        "⚠️ REQUIRES EXPLICIT USER CONFIRMATION before executing: show the user market, side, order_type, price, volume, and total notional, then wait for explicit approval. Do NOT place the order without user confirmation. " +
        'Example call: {"market":"KRW-BTC","side":"bid","order_type":"limit","price":"50000000","volume":"0.0001"} ' +
        "CLI-first: when the Bithumb CLI is installed, prefer the documented `bithumb ...` CLI command for this write operation; use this MCP tool as fallback when the CLI is unavailable/fails or the user explicitly asks for MCP.",
      isWrite: true,
      inputSchema: {
        type: "object",
        properties: {
          market: {
            type: "string",
            description: "Market code, e.g. KRW-BTC",
          },
          side: {
            type: "string",
            enum: ["bid", "ask"],
            description: "Order side: bid (buy) or ask (sell)",
          },
          order_type: {
            type: "string",
            enum: ["limit", "price", "market"],
            description:
              "Order type: limit, price (market buy), market (market sell). " +
              "Note: Bithumb API response field is `ord_type` (not `order_type`).",
          },
          price: {
            type: "string",
            description: "Order price (required for limit and price orders)",
          },
          volume: {
            type: "string",
            description:
              "Order volume (required for limit and market orders)",
          },
          client_order_id: {
            type: "string",
            description: "Client-assigned order ID for idempotency (1–36 chars; letters, digits, hyphens, underscores only)",
          },
        },
        required: ["market", "side", "order_type"],
      },
      handler: async (rawArgs, context) => {
        const args = asRecord(rawArgs);
        const response = await context.client.privatePost(
          "/v2/orders",
          compactObject({
            market: requireString(args, "market"),
            side: requireString(args, "side"),
            order_type: requireString(args, "order_type"),
            price: readString(args, "price"),
            volume: readString(args, "volume"),
            client_order_id: readString(args, "client_order_id"),
          }),
          orderRateLimit("trade_place_order"),
        );
        return normalizeResponse(response);
      },
    },

    // ── 4. trade_cancel_order ──────────────────────────────────────
    {
      name: "trade_cancel_order",
      module: "trade",
      description:
        "주문을 취소합니다. Cancel an order by order_id or client_order_id. " +
        "ID 라우팅: 사용자가 명시적으로 'client-order-id'라고 표현했으면 즉시 client_order_id로 취소 시도. " +
        "그 외에는 order_id로 먼저 취소 시도 → 결과가 없으면(order_not_found / 404) client_order_id로 다시 시도(폴백)한다. " +
        "Bithumb은 client_order_id 형식을 강제하지 않아 사용자가 order_id 패턴과 동일하게 만들 수 있으므로 입력값으로 추측하지 않는다. " +
        "⚠️ REQUIRES EXPLICIT USER CONFIRMATION before executing: show the user the order details (order_id or client_order_id) and wait for explicit approval. Do NOT cancel without user confirmation. " +
        "CLI-first: when the Bithumb CLI is installed, prefer the documented `bithumb ...` CLI command for this write operation; use this MCP tool as fallback when the CLI is unavailable/fails or the user explicitly asks for MCP.",
      isWrite: true,
      inputSchema: {
        type: "object",
        properties: {
          order_id: {
            type: "string",
            description: "Order ID to cancel",
          },
          client_order_id: {
            type: "string",
            description: "Client-assigned order ID to cancel (1–36 chars; letters, digits, hyphens, underscores only)",
          },
        },
        required: [],
      },
      handler: async (rawArgs, context) => {
        const args = asRecord(rawArgs);
        const response = await context.client.privateDelete(
          "/v2/order",
          compactObject({
            order_id: readString(args, "order_id"),
            client_order_id: readString(args, "client_order_id"),
          }),
          orderRateLimit("trade_cancel_order"),
        );
        return normalizeResponse(response);
      },
    },

    // ── 5. trade_batch_place ───────────────────────────────────────
    {
      name: "trade_batch_place",
      module: "trade",
      description:
        "다건 주문을 요청합니다. Place multiple orders in a single batch (max 20). " +
        "Use when: user asks for multiple orders at once (e.g., grid orders, simultaneous BTC+ETH limit buys). " +
        "Do NOT use: for a single order (use trade_place_order); for time-sliced execution (use twap_place). " +
        "Each order item field: `order_type` (canonical) ∈ {limit, price, market}. " +
        "각 limit 주문의 price는 출처와 무관하게 호가단위(price tick)에 정렬돼야 한다. 정렬되지 않은 값은 round 정규화 후 확인 단계에서 원본/보정값을 함께 보여준다 (bithumb-trade 스킬 order-commands.md). " +
        "Partial-failure semantics: each item may succeed or fail independently. Do NOT auto-retry failed items; surface them to the user. " +
        "⚠️ REQUIRES EXPLICIT USER CONFIRMATION before executing: read all orders back to the user (market, side, order_type, price, volume for each) and wait for explicit approval. Do NOT place any order without user confirmation. " +
        'Example call: {"batch_orders":[{"market":"KRW-BTC","side":"bid","order_type":"limit","price":"50000000","volume":"0.0001"},{"market":"KRW-ETH","side":"bid","order_type":"limit","price":"4500000","volume":"0.001"}]} ' +
        "CLI-first: when the Bithumb CLI is installed, prefer the documented `bithumb ...` CLI command for this write operation; use this MCP tool as fallback when the CLI is unavailable/fails or the user explicitly asks for MCP.",
      isWrite: true,
      inputSchema: {
        type: "object",
        properties: {
          batch_orders: {
            type: "array",
            items: {
              type: "object",
              properties: {
                market: { type: "string", description: "Market code, e.g. KRW-BTC" },
                side: { type: "string", enum: ["bid", "ask"], description: "Order side" },
                order_type: { type: "string", enum: ["limit", "price", "market"], description: "Order type" },
                price: { type: "string", description: "Order price" },
                volume: { type: "string", description: "Order volume" },
                client_order_id: { type: "string", description: "Client-assigned order ID (1–36 chars; letters, digits, hyphens, underscores only)" },
              },
              required: ["market", "side", "order_type"],
            },
            description: "Array of order objects (max 20)",
          },
        },
        required: ["batch_orders"],
      },
      handler: async (rawArgs, context) => {
        const args = asRecord(rawArgs);
        const batchOrders = args.batch_orders;
        if (!Array.isArray(batchOrders) || batchOrders.length === 0) {
          throw new ValidationError(
            "Missing required parameter \"batch_orders\".",
            "Provide an array of order objects.",
          );
        }
        const response = await context.client.privatePost(
          "/v2/orders/batch",
          { batch_orders: batchOrders },
          orderRateLimit("trade_batch_place"),
        );
        return normalizeResponse(response);
      },
    },

    // ── 6. trade_batch_cancel ──────────────────────────────────────
    {
      name: "trade_batch_cancel",
      module: "trade",
      description:
        "다건 주문을 취소합니다. Cancel multiple orders (max 30). Provide order_ids or client_order_ids. " +
        "⚠️ REQUIRES EXPLICIT USER CONFIRMATION before executing: show the user all order IDs to be cancelled and wait for explicit approval. Do NOT cancel without user confirmation. " +
        "CLI-first: when the Bithumb CLI is installed, prefer the documented `bithumb ...` CLI command for this write operation; use this MCP tool as fallback when the CLI is unavailable/fails or the user explicitly asks for MCP.",
      isWrite: true,
      inputSchema: {
        type: "object",
        properties: {
          order_ids: {
            type: "array",
            items: { type: "string" },
            description: "List of order IDs to cancel (max 30)",
          },
          client_order_ids: {
            type: "array",
            items: { type: "string" },
            description: "List of client-assigned order IDs to cancel (max 30; each id 1–36 chars; letters, digits, hyphens, underscores only)",
          },
        },
        required: [],
      },
      handler: async (rawArgs, context) => {
        const args = asRecord(rawArgs);
        const response = await context.client.privatePost(
          "/v2/orders/cancel",
          compactObject({
            order_ids: readStringArray(args, "order_ids"),
            client_order_ids: readStringArray(args, "client_order_ids"),
          }),
          orderRateLimit("trade_batch_cancel"),
        );
        return normalizeResponse(response);
      },
    },
  ];
}
